// Üretilen dosya: tool/ozgun/uret.py. Sanat · Dekoratif sanatlar: seramik, cam, tekstil, mobilya, kuyumculuk (orta).
const ozArt14Orta = <(String, String, List<String>, String)>[
  ('Atom düzeni bakımından cam, aşağıdaki katı türlerinden hangisine girer?', 'Amorf (düzensiz yapılı) katı', ['Tek kristalli katı', 'Çok kristalli metalik katı', 'Moleküler kristal'], 'Cam soğurken atomları düzenli bir kristal örgü kuramaz; bu yüzden belirgin bir erime noktası yoktur ve amorf katı sayılır.'),
  ('Antik Mısır ve Mezopotamya\'da cam kaplar için kullanılan \'çekirdek\' tekniğinde işlem nasıl yürür?', 'Kum-kil çekirdeğe sıcak cam sarılır, sonra çekirdek kazınarak çıkarılır', ['Erimiş cam, ısıya dayanıklı bir kalıba dökülüp sıkıştırılır ve soğutulur', 'Cam hamuru uzun bir boruyla üflenip havada şişirilerek biçimlendirilir', 'Cam levhalar fırında birbirine eritilerek kaynaştırılır'], 'Üfleme borusu bilinmediği için küçük kaplar önce kum-kil bir çekirdek üzerinde biçimlendirilirdi; çekirdek sonradan çıkarılırdı.'),
  ('Cam üfleme borusunun bulunuşu, Roma çağı cam üretimini nasıl değiştirmiştir?', 'Camı hızlı ve ucuz kap üretimine açarak yaygınlaştırmıştır', ['Camı yalnız saray ve tapınak atölyelerine özgü, ulaşılmaz bir lüks hâline getirmiştir', 'Cam kapların üretimini durdurup yerine seramik kapların yaygınlaşmasına yol açmıştır', 'Camın yalnız mücevher yapımında kullanılmasını sağlamıştır'], 'Üfleme, MÖ 1. yüzyılda Suriye-Filistin çevresinde bulunmuştur; kapların kısa sürede biçimlendirilmesi cam eşyayı sıradan insanın da alabileceği hâle getirmiştir.'),
  ('Kırmızı renkli \'altın yakut\' camını elde etmek için cam hamuruna katılan madde hangisidir?', 'Altın klorür', ['Kobalt oksit', 'Bakır sülfat', 'Mangan dioksit'], 'Küçük miktarda altın bileşiği, cama kırmızı-pembe bir renk verir. Kobalt mavi, mangan mor, demir yeşil tonlar verir.'),
  ('İngiliz George Ravenscroft\'un 17. yüzyılda geliştirdiği kurşun kristalin sıradan cama göre sağladığı en belirgin üstünlük nedir?', 'Yüksek parlaklık ve ışığı daha güçlü kırması', ['Çok daha düşük bir ağırlık ve elde tutulduğunda çok hafif olması', 'Isıya karşı daha yüksek dayanım ve kaynar suyla temasa uygunluk', 'Hiç kırılmaması ve darbeye karşı çelik gibi dayanıklı olması'], 'Kurşun oksit camın kırılma indisini artırır; böylece oyma yüzeylerde ışık güçlü biçimde parlar. Kurşun kristal ağırdır ve kırılgandır.'),
  ('Pyrex ve benzeri laboratuvar camlarının ani ısı değişimine dayanıklı olmasının nedeni nedir?', 'Bor trioksit katkısıyla genleşme katsayısının çok düşük olması', ['Camın içinden geçirilen ince bakır tel örgünün gerilimi taşıması', 'Camın her yerde tam 1 cm kalınlıkta döküldüğü bir üretim kuralı', 'Camın içinde su bulunması'], 'Borosilikat cam ısınıp soğurken çok az genleşip büzülür; bu yüzden iç gerilim oluşmaz ve çatlama riski düşer.'),
  ('Üretimden çıkan cam eşyanın kontrollü ve yavaş biçimde soğutulduğu \'tavlama\' işleminin amacı nedir?', 'İç gerilimleri gidererek eşyanın sonradan çatlamasını önlemek', ['Camı renklendirmek', 'Camın yüzeyini aşındırarak mat yapmak', 'Camın ağırlığını azaltmak'], 'Hızlı soğuyan cam içte gerilim biriktirir ve kendiliğinden çatlayabilir. Tavlama fırınında sıcaklık yavaşça düşürülerek bu gerilim giderilir.'),
  ('Farklı renkli cam katmanların üst üste bindirilip dış katmanın oyularak desen elde edildiği işçilik hangi adla anılır?', 'Katmanlı (overlay/casing) cam oyma', ['Kabartma baskı', 'Monotip', 'Fitil dokuma'], 'Üst üste geçirilen renkli tabakaların bazıları oyulunca alttaki renk görünür. Bohemya ve Çin cam ustaları bu yöntemi yüzyıllarca kullanmıştır.'),
  ('Cam kabın yüzeyine altın ya da emaye boyayla yapılan fırınlanmış süslemenin, 13-14. yüzyıl Suriye ve Mısır\'da öne çıkan ünlü ürünleri hangileridir?', 'Memlük dönemi emaye ve yaldız süslü cam kandiller', ['Roma mozaik zemin levhaları', 'Gotik vitray rozetleri', 'Barok ayna çerçeveleri'], 'Memlük camcıları, mescit kandillerini emaye ve yaldızla süsleyip üzerine yazı kuşakları yerleştirmişlerdir. Bunlar İslam cam sanatının zirvesi sayılır.'),
  ('15. yüzyılda Angelo Barovier\'in Murano\'da geliştirdiği ve Venedik camını ünlendiren \'cristallo\' neyi ifade eder?', 'Neredeyse renksiz ve berrak bir cam', ['Opak süt beyazı cam', 'Altın parçacıklı cam', 'Siyah cam'], 'Barovier, camdaki renk veren safsızlıkları gidererek doğal kristale benzeyen çok berrak bir cam elde etmiş; bu cam Avrupa\'da yüzyıllarca taklit edilmiştir.'),
  ('Bohemya (Çek) camının 17. yüzyılda öne çıkma nedeni olarak en sık gösterilen özellik hangisidir?', 'Potas-kireç camının sert ve renksiz olup oyma işçiliğine elverişli olması', ['Camın yalnızca yeşil renkte ve çok kalın duvarlı biçimde üretilmesi', 'Kurşunun kullanımının yasaklanıp yalnız soda camının serbest bırakılması', 'Cam yerine seramik kullanılması'], 'Bohemya\'nın ormanları potas için odun külü sağlıyordu. Sert ve berrak cam, tekerlekle oyma ve gravüre çok elverişliydi.'),
  ('Waterford kristalinin ünlendiği İrlanda\'daki cam atölyesi hangi yüzyılın sonlarında kurulmuştur?', '18. yüzyıl', ['13. yüzyıl', '16. yüzyıl', '20. yüzyıl'], 'Waterford\'daki cam fabrikası 1783\'te kurulmuş; elmas kesim desenli ağır kurşun kristali ile ünlenmiştir.'),
  ('Alvar Aalto\'nun 1936\'da tasarladığı dalgalı kenarlı \'Savoy Vazosu\', adını nereden almıştır?', 'Helsinki\'deki bir restorandan', ['Bir mühendis ailenin adından', 'Bir cam fabrikasının kurucusundan', 'Bir İsveç şehrinden'], 'Vazo, Aalto\'nun iç mekânını tasarladığı Helsinki\'deki Savoy Restoranı için hazırlanmış; serbest akışlı organik biçimi İskandinav tasarımının simgelerinden olmuştur.'),
  ('Paşabahçe cam fabrikası hangi yılda kurulmuştur?', '1935', ['1890', '1952', '1978'], 'Paşabahçe fabrikası, Cumhuriyet\'in sanayileşme çabalarının bir parçası olarak 1935\'te İstanbul Beykoz\'da İş Bankası öncülüğünde açılmıştır; Türkiye\'de modern cam sanayisinin başlangıcı sayılır.'),
  ('Cam sanayinde seri üretimle el işçiliğinin karşılaştırıldığı bir değerlendirmede, kalıp üfleme yönteminin el üfleme yöntemine göre başlıca avantajı nedir?', 'Aynı biçimde çok sayıda ürünü hızla elde etmek', ['Her parçanın tek bir usta tarafından benzersiz biçimde yapılabilmesi', 'Ürünlerin kalıp izi taşımayıp tamamen kusursuz görünmesi', 'Camın renginin değişmesi'], 'Kalıba üflenen cam hep aynı biçimi aldığından üretim hızlanır ve maliyet düşer; ancak el üflemedeki serbest biçim çeşitliliği azalır.'),
  ('Müzede bir cam parçanın dibinde pürüzlü bir dairesel iz görüldüğünde bu iz neyi gösterir?', 'Parçanın işlenirken pontil çubuğuna tutturulduğunu', ['Parçanın kalıpta basıldığını', 'Parçanın asitle dağlandığını', 'Parçanın tavlanmadığını'], 'Pontil izi, üfleme borusundan ayrılan işin çubuğa yapıştırıldığı yeri işaret eder. Bu iz el yapımı olduğunu ve üfleme tekniğini düşündürür.'),
  ('Aynı gün üretilen iki kristal kadehten biri ağır ve parlak, diğeri hafif ve daha az parlak. Bu farkı hangi madde açıklar?', 'Ağır olana kurşun oksit katılmış olması', ['Hafif olanın içinde daha fazla kum bulunması ve bu yüzden daha az ışık kırması', 'Parlak olanın dış yüzeyinin sonradan ince bir boya tabakasıyla kaplanmış olması', 'Hafif olanın tavlanmamış olması'], 'Kurşun oksit yoğunluğu ve kırılma indisini artırır; böylece kristal ağır ve parlak olur. Kurşunsuz camlar daha hafif ve daha az pırıltılıdır.'),
  ('Yüksek ısıya dayanıklı mutfak kapları ile ince şampanya kadehleri arasında malzeme tercihinin farklı olması hangi ölçüte dayanır?', 'Isı dayanımı ile berraklık ve işlenebilirlik arasındaki dengeye', ['Yalnızca ürünlerin satış fiyatına ve piyasada bulunabilirliğine', 'Yalnızca camın rengine ve camın hangi ülkede üretildiğine', 'Üretildikleri ülkeye'], 'Borosilikat cam ısı şokuna dayanır; kurşun kristal ise parlak ve işlemeye uygundur. Kullanım amacı malzemeyi belirler.'),
  ('Taş hamur (stoneware) ile çanak çömlek arasındaki en önemli teknik fark nedir?', 'Taş hamur daha yüksek ısıda pişip camsılaştığı için sırsız bile su tutabilir', ['Taş hamur hiç pişirilmez, kurutulduktan sonra doğrudan kullanılır', 'Çanak çömlek yarı saydam olduğu için su tutar, taş hamur ise tutamaz', 'Taş hamur yalnız Çin\'de üretilir'], 'Taş hamur yaklaşık 1200-1300 °C\'de pişer; killer kısmen camsılaşır, gövde sıkı ve geçirimsiz olur. Çanak çömlek daha gözenekli kalır.'),
  ('Kemik porseleni (bone china) İngiltere\'de ünlenmiş bir hamur türüdür. Hamura katılan ve ona sıcak, yarı saydam bir beyazlık veren madde nedir?', 'Hayvan kemiği külü', ['Kurşun oksit', 'Kobalt oksit', 'Pirinç kabuğu külü'], 'Kemik külü, hamura yüksek beyazlık ve ince, yarı saydam gövde kazandırır. Yöntem 18. yüzyılın sonlarında Josiah Spode tarafından geliştirilmiştir.'),
  ('Johann Friedrich Böttger\'in 1708\'de Almanya\'da başardığı ve Avrupa\'nın yıllarca aradığı buluş neydi?', 'Avrupa\'da ilk sert hamurlu porselenin üretilmesi', ['Cam üflemenin ve renkli vitray tekniğinin birlikte bulunması', 'Kobalt mavisi sırın ve altın yaldızın Avrupa atölyelerinde bulunması', 'Kil çarkının bulunması'], 'Böttger, Saksonya Prensi II. Augustus\'un isteğiyle çalışırken Ehrenfried von Tschirnhaus\'la birlikte Çin tipi sert porseleni yapmayı başardı; 1710\'da Meissen manufakturası kuruldu.'),
  ('Meissen porselen manufakturasının ürünlerini ayırt eden ve dünyanın en eski porselen markalarından biri olan alametifarikası nedir?', 'Çapraz iki mavi kılıç damgası', ['Altın çift başlı kartal', 'Kırmızı üç yıldız', 'Yeşil taç'], 'Meissen\'in çapraz kılıçları, Saksonya seçmen armasındaki kılıçlardan alınmıştır ve 1720\'lerden itibaren taklitleri önlemek için kullanılmıştır.'),
  ('Royal Copenhagen\'ın en tanınmış desenlerinden biri olan \'Blue Fluted\' hangi renk düzenine sahiptir?', 'Beyaz zemin üzerine kobalt mavisi', ['Mavi zemin üzerine altın yaldız', 'Siyah zemin üzerine kırmızı', 'Yeşil zemin üzerine beyaz'], 'Danimarka\'nın kraliyet porseleni, 1775\'te kurulmuş; mavi-beyaz kombinasyonuyla Çin etkisini Kuzey Avrupa zevkine uyarlamıştır.'),
  ('Fransa\'nın merkezinde kaolin yataklarının bulunmasıyla 18. yüzyıl sonunda porselen sanayisinin merkezi hâline gelen kent hangisidir?', 'Limoges', ['Marsilya', 'Strasbourg', 'Bordeaux'], 'Saint-Yrieix\'te kaolin bulunması Limoges\'i sert hamurlu porselenin merkezi yapmıştır; kent bugün de porselen ve emaye ile anılır.'),
  ('Seramik fırınında gövdenin sırla kaplandıktan sonra sır eriyip camlaşıncaya dek yüksek ısıda pişirilmesine ne ad verilir?', 'Sır (glost) pişirimi', ['Kurutma', 'Çarkta atma', 'Astarlama'], 'Sırlanmış gövde fırında yeniden ısıtılır; sır erir ve yüzeyde sert, parlak camsı bir tabaka oluşturur.'),
  ('Fırın atmosferinde oksijenin yetersiz olduğu pişirim türü, sırdaki metal oksitlerin renklerini nasıl etkiler?', 'Bakır sırın kırmızıya, demirli sırın yeşile döndüğü seladon etkisi doğar', ['Bütün sırlar renksiz kalır ve fırından beyaz çıkar', 'Sır fırında hiç erimez; yalnız kil gövdesi kızarır', 'Tüm sırlar parlak sarıya döner'], 'İndirgen (redüksiyon) pişirimde oksijen azdır; bakır kırmızı, demir yeşilimsi seladon renkleri verir. Oksitleyici pişirimde sonuç farklıdır.'),
  ('Seramik üretiminde fırından çıkan bir parçanın sırının atlaması ya da kabarcıklanması en çok hangi hatadan kaynaklanır?', 'Kabın tam kurumadan sırlanıp pişirilmesi veya yetersiz biskü hazırlığı', ['Fırının gereğinden fazla soğuk kalması ve sıcaklığın yavaş artması', 'Kilin fazla beyaz olması ve hamura çok az su katılması', 'Fırçanın yumuşak olması'], 'Nem fırında buharlaşıp sırın altında basınç yapar; sır kabarır veya atlar. Bu yüzden gövde tam kurutulmalı, sırlama düzgün yapılmalıdır.'),
  ('Aynı fırında pişirilen iki vazodan biri çanak çömlek, diğeri porselen olsaydı fırın sıcaklığı ne olmalıydı?', 'Porselen için çanak çömlekten çok daha yüksek bir ısı gerekirdi', ['İki hamur için de aynı sıcaklık yeterli olurdu, fark hamur rengindedir', 'Çanak çömlek için porselenden çok daha yüksek bir ısı gerekirdi', 'Isı önemli olmazdı'], 'Çanak çömlek yaklaşık 1000-1150 °C\'de pişerken sert hamurlu porselen yaklaşık 1280-1400 °C ister; bu yüzden aynı fırın programı iki hamurda ortak kullanılmaz.'),
  ('Song Hanedanı döneminde \'beş ünlü fırın\' arasında sayılan, genellikle krem beyazı, sade oyma ya da kalıp desenli porselenleriyle tanınan merkez hangisidir?', 'Ding', ['Jingdezhen', 'Satsuma', 'Hagi'], 'Ding fırınları, filiz gibi ince oyma ve kalıpla basılmış çiçek desenli krem beyazı ürünleriyle bilinir. Sade biçim, Song estetiğinin simgesidir.'),
  ('Çin porselen vazolarının altındaki \'nianhao\' damgasının amacı genellikle nedir?', 'İmparatorluk hükümdarının saltanat dönemini belirtmek', ['Kabı yapan fırın ustasının adını ve doğum yerini yazmak', 'Fırında pişirilme sıcaklığını ve süresini kayda geçirmek', 'Satış fiyatını belirtmek'], 'Nianhao, hangi imparatorun döneminde yapıldığını gösteren dört veya altı harfli damgadır. Sonraki dönemlerde saygı ya da taklit amacıyla eski damgalar da kullanılmıştır.'),
  ('Japonya\'da Bizen seramiği geleneksel olarak nasıl üretilir?', 'Sırsız, odunla yakılan fırında, kül ve alevin yüzeyde kırmızı-kahve izler bırakmasıyla', ['Altın yaldızla süslenip parlak sırla kaplanarak ve çini mürekkebiyle boyanarak', 'Kalıpla dökülüp elektrikli fabrika fırınında seri olarak pişirilerek', 'Kalıpla dökülüp fabrikada pişirilerek'], 'Bizen eşyası sır sürülmeden pişirilir; doğal kül, alev ve fırın içi konumu yüzeye rastlantısal desenler verir. Bu yüzden her parça farklıdır.'),
  ('Kore\'de Goryeo Hanedanı döneminde (12. yüzyıl) zirveye ulaşan ve yeşilimsi sırlı gövdeye oyma kazıma dekorlu seramik hangisidir?', 'Goryeo seladonu', ['Buncheong', 'Ay kavanozu', 'Imari'], 'Goryeo seladonu, soluk yeşil sırı ve sanggam kakmalı desenleriyle Çin seladonundan farklı bir üslup kazanmış, Kore sanatının simgelerinden biri olmuştur.'),
  ('Kore\'de Joseon döneminde yapılan, yuvarlak ve hafif asimetrik biçimiyle sadeliğin simgesi sayılan ve iki yarım kasenin birleştirilmesiyle elde edilen büyük beyaz porselen kaba ne ad verilir?', 'Ay kavanozu', ['Çay kutusu', 'Zafer kâsesi', 'Mingqi'], 'Ay kavanozları 17.-18. yüzyıl Joseon beyaz porseleninin tipik örneğidir; iki yarım küre ayrı çarkta yapılıp birleştirilir, bu yüzden hafif biçim farkları taşır.'),
  ('Çatalhöyük, Hacılar ve Halaf kültürleri Anadolu ve çevresinde nasıl bir tarihsel dönemin seramikleriyle anılır?', 'Neolitik (Cilalı Taş) çağı', ['Demir Çağı', 'Hellenistik dönem', 'Selçuklu dönemi'], 'Seramik, tarıma geçişle birlikte Neolitik çağda yaygınlaşmıştır. Halaf ve Hacılar boyalı kapları o dönemin ustalığını gösterir.'),
  ('Bernard Palissy\'nin 16. yüzyılda Fransa\'da ünlendiği seramik tarzının ayırt edici özelliği nedir?', 'Kaplara yılan, balık ve kurbağa gibi gerçek hayvanların kalıpla alınıp canlı sırlarla boyanması', ['Yalnızca beyaz, sırsız ve süssüz sade porselen kapların üretilmesi', 'Çin mavi-beyazını birebir taklit eden kobalt boyalı kapların yapılması', 'Camla birleştirilen vitray vazolar'], 'Palissy\'nin \'rustik\' tabakları kalıplanmış gerçek sürüngen ve deniz canlılarıyla süslüdür; bu üslup 19. yüzyılda \'Palissy ware\' adıyla canlandırılmıştır.'),
  ('Hollanda\'daki Delft\'te üretilen mavi-beyaz kalay sırlı seramiğin 17. yüzyılda yükselişini hangi dış etken tetiklemiştir?', 'Çin porselen ithalatının aksaması ve yerine koyma talebi', ['Altın ihracatının yasaklanması ve Hollanda\'da altın kap yapımının başlaması', 'Cam üretiminin durması ve cam yerine seramiğe yönelinmesi', 'Renkli sırın icadı'], 'Çin\'deki Ming\'den Qing\'e geçiş karışıklığı porselen ihracatını kesintiye uğrattı. Delft ustaları boşluğu mavi-beyaz kalay sırlı çanak çömlekle doldurdu.'),
  ('Üç ana bağlantıdan biri olan dimi (twill) dokumanın yüzeyde bıraktığı tipik görünüm nedir?', 'Çapraz, eğik paralel çizgiler', ['Tamamen düz, çizgisiz ve yekpare görünen pürüzsüz bir yüzey', 'Kabarık, kesilmiş havlardan oluşan yumuşak ve tüylü bir doku', 'Ağ gibi açık delikler'], 'Atkı ipliği çözgülerin üzerinden ve altından kaydırılarak geçirilince çapraz kaburgalar oluşur; kot kumaşı (denim) bu bağlantıyla dokunur.'),
  ('Saten bağlantısının kumaşa verdiği en belirgin görünüm özelliği nedir?', 'Uzun iplik atlamalarıyla parlak ve düz bir yüzey', ['Kaba, mat ve belirgin biçimde dokulu bir yüzey', 'Yüzeyde havlı tüyler', 'Kare biçimli, iplik kesişimlerinin görüldüğü ızgara görüntüsü'], 'Satende iplikler çok sayıda ipliğin üzerinden atlayarak gittiğinden yüzey pürüzsüz ve ışığı yansıtan bir görünüm kazanır.'),
  ('Aynı iplikle dokunup yalnız bağlantı farkıyla parlak ve mat alanlar oluşturularak desenin belirdiği, adı Şam kentiyle anılan ipek kumaş hangisidir?', 'Damask', ['Tafta', 'Muslin', 'Kadife'], 'Damask\'ta desen ile zemin bez ve saten bağlantısının zıtlığıyla ortaya çıkar; kumaş ters çevrildiğinde desenin parlak-mat durumu tersine döner.'),
  ('Kadife, kumaş türü olarak hangi özelliğiyle diğerlerinden ayrılır?', 'Yüzeyi kısa, sık ve yumuşak havlarla kaplıdır', ['Yüzeyi tamamen pürüzsüz, parlak ve havsız bir tabakadan oluşur', 'Delikli, ajurlu ve dantel benzeri açık bir yapıya sahiptir', 'Havsız kaba dokumadır'], 'Kadife, çözgü ya da ek iplik ilmeklerinin kesilmesiyle havlı yüzey oluşturur. İtalya\'da Lucca, Venedik ve Floransa Orta Çağ\'da ünlü merkezlerdir.'),
  ('İnce, saydam pamuklu kumaşın adı olan \'muslin\', hangi şehrin adından türemiştir?', 'Musul', ['Marsilya', 'Mumbai', 'Münih'], 'Muslin adı Irak\'taki Musul kentinden gelir; Avrupalı tüccarlar ince pamuklu kumaşı ilk orada görmüştür. Dakka ise ürünün en ince biçiminin ünlü merkezi olmuştur.'),
  ('Yün liflerinin ısıyı iyi tutmasının başlıca nedeni nedir?', 'Lifteki kıvrımların hava hapsetmesi', ['Liflerin çok parlak olması', 'Lifin su geçirmez bir yağla kaplı olması', 'Liflerin metalik içermesi'], 'Yün lifi kıvrımlıdır; bu kıvrımlar arasında hapsolan hava yalıtım sağlar. Aynı nedenle yün soğuk iklimlerde giysi ve halı için uygundur.'),
  ('John Kay\'in 1733\'te icat ettiği \'uçan mekik\'in dokumacılığa katkısı nedir?', 'Mekiğin eli kullanmadan hızla atılarak daha geniş kumaş dokunabilmesi', ['İpliklerin tezgâhta otomatik olarak çok renkli boyanması', 'Pamuğun çekirdeklerinden ayrılması ve balyalanması', 'Atkıların çok renkli yapılması'], 'Uçan mekik, atkı ipliğinin çözgü arasından tek elle hızlı biçimde geçirilmesini sağladı; dokuma hızlandı ve iplik talebi arttı.'),
  ('James Hargreaves\'in 1764\'te geliştirdiği \'Spinning Jenny\' neyi mümkün kılmıştır?', 'Birden fazla iğ ile aynı anda iplik eğirmeyi', ['Atkı ipliğinin mekikle çözgüler arasından hızla geçirilmesini', 'Pamuğun tohumlarından ayrılmasını ve temizlenmesini', 'Kumaş boyamayı'], 'Spinning Jenny, tek işçinin birçok iğ çevirmesine olanak vererek iplik üretimini çok artırmış ve sanayi devriminin tekstil kolunda önemli rol oynamıştır.'),
  ('Joseph Marie Jacquard\'ın 1804-1805 dolaylarında dokuma tezgâhına eklediği delikli kartlar neyi sağlamıştır?', 'Karmaşık desenlerin tezgâhta otomatik biçimde işlenmesini', ['İpek ipliklerinin tezgâhta kendi kendine boyanmasını ve beyazlamasını', 'İplik eğirme hızının tek işçiyle birkaç kat artmasını', 'Tezgâhın buhar gücüyle çalışmasını'], 'Delikli kart dizisi hangi çözgü ipliğinin kalkacağını belirler; desen değiştirmek için yalnız kartlar değiştirilir. Fikir, sonradan bilgisayar tarihinde de önemli sayılmıştır.'),
  ('Eli Whitney\'nin 1793\'te ürettiği \'cotton gin\' ne işe yarar?', 'Pamuğu çekirdeğinden hızla ayırır', ['Pamuk lifini iplik hâline getirmek için eğirmeye hazırlar', 'Dokunmuş kumaşı beyazlatır ve ağartma işlemini kolaylaştırır', 'Kumaşa desen basar'], 'Çırçır makinesi, pamuğun tohumlarını kısa sürede ayırarak Güney ABD\'de pamuk tarımını kârlı kıldı; bu da kölelik düzeninin güçlenmesine yol açtı.'),
  ('Bir kumaşın bir yüzü parlak, diğer yüzü mat ise bu özelliği veren bağlantı en olası hangisidir?', 'Saten', ['Bez bağlantı', 'Hasır örgü', 'Dimi bağlantı'], 'Saten bağlantıda iplikler bir yüzde uzun atlamalarla uzandığından o yüz parlak, ters yüz daha mat ve kaba olur.'),
  ('Bir moda tasarımcısı dökümlü, kayganlığı yüksek, parlak bir elbise kumaşı arıyor. Hangi lif ve bağlantı birleşimi en uygundur?', 'İpek ipliğinden saten', ['Kenevir ipliğinden bez', 'Yünden dimi', 'Pamuktan kaba keten bağlantı'], 'İpek lifi ince ve düzgün, saten bağlantısı pürüzsüz olduğundan ışığı yansıtan akışkan bir kumaş verir.'),
  ('İpek Yolu en doğru biçimde nasıl tanımlanır?', 'Çin\'den Akdeniz\'e uzanan, ipek ve diğer malları taşıyan kervan ve deniz ticaret ağı', ['Yalnız Çin sınırı içinde, Pekin ile Şanghay arasında kurulmuş bir kanal sistemi', 'Avrupa\'dan Amerika kıtasına uzanan ve baharat taşıyan bir deniz yolu', 'Sadece Hindistan\'daki bir kervan yolu'], 'İpek Yolu tek bir yol değil, bin yıldan fazla süren bir ağdı; ipek, baharat, porselen ve fikirler Anadolu üzerinden Avrupa\'ya taşındı.'),
  ('Çözgü ya da atkı iplikleri dokumadan önce bağlanıp boyanarak, kumaş dokunurken desenin belirdiği tekniğe ne ad verilir?', 'Ikat', ['Batik', 'Chintz', 'Toile'], 'İkat\'ta bağlanan kısımlar boyayı almadığından desen dokuma sırasında ortaya çıkar; kenarları hafif bulanık görünmesi tekniğin belirgin işaretidir. Özbekistan\'da \'abr\' (bulut) adıyla bilinir.'),
  ('Koşenil (cochineal) adlı kırmızı boya hangi kaynaktan elde edilir?', 'Kaktüsler üzerinde yaşayan böceğin kurutulmuş dişilerinden', ['Bir deniz salyangozunun salgı bezlerinden damıtılarak', 'Bir ağacın kabuğunun kaynatılıp süzülmesiyle', 'Bir madenin öğütülüp oksitlenmesiyle'], 'Koşenil böceği (Dactylopius coccus) Orta ve Güney Amerika\'da yetişir; Aztekler ve İnkalar bu boyayı kullanmış, İspanyollar Avrupa\'ya götürmüştür.'),
  ('William Perkin\'in 1856\'da, sıtma ilacı kinin sentezi denemesi sırasında rastlantı sonucu bulduğu \'mauveine\' neden önemlidir?', 'İlk sentetik (anilin) boya olması ve boya sanayisini başlatması', ['İlk plastik malzeme olması ve plastik sanayisini başlatması', 'İlk yapay lif olması', 'Camın renklendirilmesinde ilk kez kullanılan metal oksit olması'], 'Perkin\'in mor boyası kömür katranından elde edildi. Bu buluş yapay boya endüstrisine yol açtı ve doğal boyaların yerini aldı.'),
  ('Finlandiya\'da 1951\'de kurulan ve Maija Isola\'nın 1964 tarihli iri çiçekli \'Unikko\' (haşhaş) deseniyle tanınan tekstil markası hangisidir?', 'Marimekko', ['Liberty', 'Orrefors', 'Arabia'], 'Marimekko, 1950\'lerden itibaren iri, cesur renkli baskılarıyla modern İskandinav tekstil tasarımının simgesi hâline gelmiştir.'),
  ('Fransa\'da XIV. Louis döneminde Colbert\'in 1662\'de kraliyet atölyesi hâline getirdiği Paris\'teki gobelen üretim merkezinin adı nedir?', 'Gobelins Manufakturası', ['Aubusson Atölyesi', 'Beauvais Atölyesi', 'Sèvres Manufakturası'], 'Gobelin ailesinin boyahanesi olan yapı, kraliyet gobelen atölyesine dönüştürülmüş, sarayın görkemli duvar halılarını Le Brun yönetiminde üretmiştir.'),
  ('Fransa\'nın Creuse bölgesindeki, gobelenleriyle UNESCO tarafından 2009\'da somut olmayan kültürel miras listesine alınan kent hangisidir?', 'Aubusson', ['Limoges', 'Tours', 'Chartres'], 'Aubusson, 15. yüzyıldan beri gobelen dokumasıyla bilinir; atölyeleri hem kraliyet hem de ev dekorasyonu için tapestri üretmiştir.'),
  ('Gobelen yapımında ressamın hazırladığı ve dokumacıya rehber olan tam boy resme ne ad verilir?', 'Karton', ['Gesso', 'Gouache', 'Palet'], 'Dokumacı, kartonun renk ve çizgilerini çözgü üzerine iplikle aktarır. Raffaello ve Le Brun gibi sanatçıların kartonları gobelen sanatında çok önemlidir.'),
  ('Japon geleneksel nakışı \'sashiko\'nun tipik görünümü hangisidir?', 'İndigo mavisi kumaş üzerine beyaz ipliğin düz dikişlerle geometrik desenler oluşturması', ['Kırmızı ipek üzerine altın ipliğin kabartmalı işlenmesi ve boncukla süslenmesi', 'Siyah zemin üzerine beyaz boncuğun sıra sıra dikilmesi ve parıltı verilmesi', 'Pamuk üzerine sırlı boya uygulanması'], 'Sashiko, aslında kumaşı güçlendirip onarmak için yapılan sade dikişlerden doğmuş; zamanla estetik bir nakış türüne dönüşmüştür.'),
  ('Louis XIV\'in baş ebenisti André-Charles Boulle\'ün adıyla anılan, kaplumbağa kabuğu ve pirinç kakmalı marküteri tekniği hangi özelliğiyle ünlüdür?', 'Kaplumbağa kabuğu ve pirinç levhaların birlikte kesilip karşılıklı desen elde edilmesi', ['Yalnız kiraz ağacından kaplama kullanılması ve metal bezemenin yasaklanması', 'Altın yaldızlı ama hiç kakma içermeyen, düz ve sade bir yüzey', 'Fildişiyle yapılan çocuk oyuncakları'], 'Boulle tekniğinde üst üste yapıştırılmış pirinç ve kabuk levha birlikte kesilir; ortaya iki ters renkli parça çıkar (birinde pirinç zemin, diğerinde kabuk zemin).'),
  ('Rokoko\'nun Fransız mobilyasındaki ayırt edici özelliği hangisidir?', 'Kıvrımlı cabriole bacaklar, asimetrik ve deniz kabuğu biçimli rocaille süslemeler', ['Dik açılı, sade, düz bacaklar ve süssüz geometrik panolar', 'Ağır, simetrik ve Mısır motifli sütunlu görünüm', 'Çelik boru iskelet'], 'Louis XV üslubunda bacaklar S biçiminde kıvrılır, çerçeveler ve çekmeceler yumuşak hatlıdır; rocaille adı kabuk biçimli süslemeden gelir.'),
  ('Louis XVI mobilyasında XV. Louis dönemine göre hangi değişiklik görülür?', 'Kıvrımlı hatlar yerine düz, sivrileşen, oluklu bacaklar ve neoklasik düzen', ['Süslemenin daha da artması, bacakların daha kıvrımlı ve çok oymalı olması', 'Mobilyanın yalnız bakır levhayla kaplanıp boyasız bırakılması', 'Mobilyanın yalnızca bambudan yapılması'], 'Louis XVI üslubunda, Pompeii ve Herculaneum keşiflerinin ışığında, düz çizgiler, ince kolonlu bacaklar ve geometrik düzen öne çıkar.'),
  ('Napolyon\'un Mısır seferinin ardından Empire mobilyasında yaygınlaşan motifler hangileridir?', 'Sfenks, lotus ve kartal gibi Mısır-Roma öğeleri', ['Rokoko kabukları ve asimetrik rocaille kıvrımları', 'Gotik sivri kemerler ve rozet biçimli oymalar', 'Çin ejderhaları'], 'Empire üslubunda maun gövdeler üzerine bronz Mısır ve Roma figürleri uygulanmış; Jacob-Desmalter atölyesi bu zevkin en tanınmış üreticisidir.'),
  ('George Hepplewhite adı hangi mobilya parçasının biçimiyle özdeşleşmiştir?', 'Kalkan biçimli sırtlıklı sandalye', ['Çekmeceli, kıvrımlı Rokoko komodin ve kaplamalı üst tablası', 'Çok kollu, kristal damlalı büyük avize ve zincir askı', 'Havlu askısı'], 'Hepplewhite\'ın 1788 tarihli rehber kitabı, kalkan biçimli sırtlık ve narin düz bacaklı sandalyelerle ünlü, zarif ve hafif bir neoklasik üslubu yaygınlaştırdı.'),
  ('Queen Anne dönemi (18. yüzyıl başı) İngiliz mobilyasında hangi bacak biçimi belirleyicidir?', 'Kıvrımlı cabriole bacak', ['Dikdörtgen kesitli, düz ve sivrileşmeyen sert köşeli bacak', 'Elle dönmüş, halka bileziklerle süslü, dik ahşap bacak', 'Çelik boru bacak'], 'Cabriole bacak, bir hayvan bacağını andıran iki yönlü kavisle yapılır ve genellikle pad foot ile biter. Bu biçim Louis XV ve Rokoko mobilyasını da etkilemiştir.'),
  ('Shaker topluluğunun mobilya anlayışını en iyi hangi ifade özetler?', 'Süssüz sadelik, işlev ve dürüst işçilik', ['Altın yaldızlı gösteriş, zengin oyma ve bol kıvrımlı süsleme', 'Rokoko kıvrımları ve asimetrik deniz kabuğu biçimleri', 'Egzotik Çin motifleri'], 'Shaker\'lar, güzelliğin işlevden doğduğuna inanıyordu; ürettikleri sandalye ve dolaplar süssüz ve çok sağlamdı. Shaker mobilyası modern tasarımı da etkilemiştir.'),
  ('Gustav Stickley\'in Amerikan Arts and Crafts hareketinde yaygınlaştırdığı \'Craftsman\' (Mission) mobilyasının tipik özelliği nedir?', 'Meşe ağacı, görünür zıvana birleşimleri ve süssüz düz hatlar', ['Cilalı maun, altın yaldız ve gizlenmiş birleşim yerleri', 'Çelik boru iskelet ve plastik oturaklarla sanayi üretimi', 'Kıvrımlı bacaklar ve kabuk motifleri'], 'Stickley meşenin doğal dokusunu ve görünen birleşimleri öne çıkaran dayanıklı mobilyalar üretmiştir; Morris koltuğu bu akımın tanınmış ürünüdür.'),
  ('Mobilyada kırlangıç kuyruğu (dovetail) birleşiminin başlıca üstünlüğü nedir?', 'Geçmeli dişlerin çekilmeye karşı çok dayanıklı olması', ['Hiç yapıştırıcı gerektirmemesi ve her çekmecenin yalnız çiviyle tutulması', 'Yalnız boyalı yüzeylerde kullanılabilmesi ve her zaman gizlenmesi', 'Yalnız boyalı yüzeylerde görülmesi'], 'Yelpaze biçimli dişler birbirine geçince çekmece gibi parçalar çekme kuvvetine karşı kilitlenir; kaliteli çekmece yapımında bunun için kullanılır.'),
  ('Louis XV dönemi Fransız mobilyasında ebeniste ve menuisier arasındaki fark nedir?', 'Ebeniste kaplamalı dolap ve komod yapar, menuisier sandalye ve çerçeve gibi oyma ahşabı işler', ['İkisi de aynı işi yapar; yalnızca farklı bölgelerde farklı adlarla anılır', 'Ebeniste yalnız metal, menuisier yalnız taş ve seramik ürünlerle uğraşır', 'Menuisier yalnız seramik üretir'], 'Fransız loncaları iş bölümünü katı tutardı: ebenistler kaplamacı, menuisier ise masif ağaç işçisi olarak ayrı loncalarda çalışırdı.'),
  ('Bir sandalye, S biçimli bacaklara, deniz kabuğu motifli oymalara ve yumuşak kıvrımlı sırtlığa sahip. Bu sandalye en olası hangi dönemdendir?', '18. yüzyıl ortası Rokoko (Louis XV)', ['20. yüzyıl başı Bauhaus (düz, yalın ve işlevsel mobilya)', '17. yüzyıl Puritan (süssüz dik hatlı mobilya)', 'Ortaçağ Gotik'], 'Kıvrımlı bacak, rocaille kabuk ve yumuşak hatlar XV. Louis dönemi Rokoko\'sunun işaretleridir; Bauhaus ve Puritan mobilyası ise sadedir.'),
  ('Mies van der Rohe\'nin 1929 Barcelona Uluslararası Fuarı\'ndaki Alman Pavyonu için Lilly Reich\'ın katkısıyla tasarladığı çapraz ayaklı, deri kaplı koltuğa ne ad verilir?', 'Barcelona koltuğu', ['Wassily koltuğu', 'Tulip koltuğu', 'Egg koltuğu'], 'Barcelona koltuğu, çelik X biçimli çerçevesi ve tufted deri minderleriyle modernizmin simgesidir; fuara gelen İspanya Kralı için yapılmıştır.'),
  ('Le Corbusier, Pierre Jeanneret ve Charlotte Perriand\'ın 1928\'de tasarladığı LC4 şezlongunun ayırt edici özelliği nedir?', 'Çelik bir tabanın üzerinde yükseklik ve eğimi ayarlanabilen gövdesi', ['Tamamen taştan yapılmış oturağı ve sabit, ayarlanamayan duruşu', 'Üç ayaklı basit ahşap yapısı ve hasır oturağı', 'Tek parça plastik kabuğu'], 'LC4, çelik taban üzerinde kayarak istenen eğime ayarlanabilen bir şezlongdur. Rahat ve işlevsel tasarımın simgesi sayılır.'),
  ('Eero Saarinen\'in 1956\'da tasarladığı, tek ayak üzerinde duran ve \'bacak karmaşasını ortadan kaldırmayı\' amaçlayan sandalye hangisidir?', 'Tulip (Lale) sandalyesi', ['Barcelona koltuğu', 'Wishbone sandalyesi', 'Windsor sandalyesi'], 'Saarinen, masa ve sandalyelerin altındaki bacak yığınını tek bir ayakla çözdü; plastik kabuk ve alüminyum ayak birleşimi 1950\'lerin geleceğe bakışını yansıtır.'),
  ('Verner Panton\'un 1960\'larda tasarladığı sandalyenin ilk kez ne tür bir yapısıyla tanınması bir dönüm noktasıdır?', 'Tek parça kalıplanmış plastikten yapılmış ilk seri sandalye', ['İlk bükme ahşap sandalye ve buhar bükme tekniğinin ilk uygulaması', 'İlk kumaş kaplı sandalye', 'İlk çelik borulu ve gergin deri kaplı sandalye'], 'Panton sandalyesi S biçimli, ayak ile oturağı birleştiren tek parça plastikten üretilmiştir; 1967\'de Vitra tarafından seri üretime geçmiştir.'),
  ('Hans Wegner\'in 1949 tarihli \'CH24\' koltuğu, sırtlığının Y biçimli oluşu nedeniyle hangi adla da anılır?', 'Wishbone (Çatal kemiği)', ['Karınca (Ant; üç bacaklı kontrplak istiflenebilir sandalye)', 'Barcelona (çapraz çelik ayaklı, tufted deri minderli koltuk)', 'Egg (Jacobsen\'in döner ayaklı kabuk koltuğu)'], 'Wegner, Çin Ming sandalyelerinden esinlenerek ahşap iskeletli, kâğıt iplikle örülü oturaklı sandalyeyi yaptı; Y biçimli sırtlık adına neden olmuştur.'),
  ('Isamu Noguchi\'nin 1947\'de tasarladığı sehpa hangi iki malzemeyle ünlüdür?', 'Cam üst tabla ve iki parçalı kıvrımlı ahşap taban', ['Mermer üst tabla ve çelik çerçeveli ayak yapısı', 'Plastik üst tabla ve parlatılmış bakır taban', 'Tuğla üst tabla ve dökme demir bacaklar'], 'Noguchi sehpasının heykel gibi kıvrımlı iki ahşap parçası birbirine geçer ve üzerine kalın cam yerleştirilir; modern Amerikan tasarımının ikonu sayılır.'),
  ('Çin Ming Hanedanı mobilyasında \'huanghuali\' adı verilen ağaç ve çivisiz zıvana birleşimleri neyi anlatır?', 'Sade çizgili, malzemenin doğal damarını öne çıkaran, ustaca geçmeli mobilya geleneğini', ['Altın yaldızlı ağır süslemeyi ve oymalı, kıvrımlı rokoko biçimlerini', 'Plastik taklit malzemeden seri üretilmiş, boyalı ve kalıplı biçimleri', 'Boyalı pamuklu döşemeyi ve çok renkli yastıklı oturma düzenini'], 'Huanghuali, Çin\'e özgü sert ve güzel damarlı bir ağaçtır; Ming mobilyası çivi ya da tutkal yerine hassas geçme birleşimlerle yapılırdı.'),
  ('Japon mobilya geleneğinde çekmeceli, kilit ve demir aksamıyla tanınan taşınabilir dolap hangi adla anılır?', 'Tansu', ['Shoji', 'Tatami', 'Byōbu'], 'Tansu, depolama için yapılan ahşap sandık ve dolap türlerini kapsar; kıyafet, kimono ve ticari belgeler için kullanılır.'),
  ('Bir modernist tasarımcı çelik boru iskelet ve gergin deriyi neden tercih eder?', 'Hafiflik, sanayide seri üretime uygunluk ve yalın görünüm sağladığı için', ['Altın rengiyle gösteriş sağladığı ve saraylarda yaygın olduğu için', 'Ahşabın hiç bulunamaması ve ormanların yasaklanması yüzünden', 'Geleneksel loncaların bu malzemeyi zorunlu tutması yüzünden'], 'Çelik boru endüstriyel olarak hazır ve ince olduğundan hafif, ekonomik ve sade mobilya yapılmasını sağlar; Bauhaus tasarımcıları bunun için ahşabın yerine boruyu seçti.'),
  ('Bir tasarımcı Chippendale ve Eames mobilyalarını kıyaslıyor. İkisinin farkını en iyi hangisi anlatır?', 'Chippendale el işçiliğine ve lüks ahşaba, Eames ise seri üretim ve yeni malzemelere dayanır', ['Her ikisi de aynı yöntemi izler; yalnız model adları ve fiyatlar farklıdır', 'Chippendale plastiği, Eames ise ahşabı hiç kullanmayı yasaklar', 'Her ikisi de aynı yüzyılda yaşamış ve aynı atölyede çalışmış ustalardır'], 'Chippendale 18. yüzyıl zanaatkâr atölyesinin ürünüdür; Eames ise 20. yüzyılda kontrplak ve fiberglas gibi malzemelerle üretim tekniği yenilemiştir.'),
  ('Gümüşte \'sterlin\' standardı, saf gümüş oranı bakımından nasıl tanımlanır?', 'Binde 925 saf gümüş içeren alaşım', ['Binde 750 saf gümüş içeren, bakır oranı çeyrek düzeyinde alaşım', 'Binde 999 saf gümüş içeren alaşım', 'Binde 500 saf gümüş içeren alaşım'], 'Sterlin gümüşü %92,5 gümüş ve çoğunlukla bakırdan oluşur; bakır katkısı saf gümüşün yumuşaklığını azaltıp eşyayı dayanıklı kılar.'),
  ('Beyaz altın, saf altının hangi metallerle alaşımlanmasıyla elde edilir?', 'Paladyum ya da nikel gibi beyaz metallerle', ['Yalnız bakırla ve çok az miktarda demirle alaşımlanarak', 'Kurşunla', 'Alüminyumla'], 'Altına paladyum veya nikel gibi metaller eklenince sarı rengi kaybolur; çoğu parça ayrıca parlak görünüm için rodyumla kaplanır.'),
  ('Altının kuyumculukta çok işlenebilen bir maden olmasında, hangi fiziksel özellik başlıca rol oynar?', 'Çok yüksek dövülebilirliği ve işlenebilirliği', ['Çok yüksek sertliği ve çelik gibi darbeye dayanıklı olması', 'Havada hızla paslanması', 'Manyetik olması'], 'Altın, çok ince tabakalara dövülebilir ve tel çekilebilir; üstelik oksitlenmez. Bu özellikler yaldız ve telkâri gibi işçilikleri mümkün kılar.'),
  ('Değerli madenlerin ağırlığının ölçülmesinde kullanılan \'troy ons\', yaklaşık kaç gramdır?', 'Yaklaşık 31,1 gram', ['Yaklaşık 28,3 gram; sıradan (avoirdupois) onsla aynı ağırlıktadır', 'Yaklaşık 16 gram', 'Yaklaşık 100 gram'], 'Troy ons, altın ve gümüş ticaretinde kullanılan standart ağırlıktır; sıradan (avoirdupois) ons olan 28,35 gramdan biraz daha ağırdır.'),
  ('Kuyumcuların \'kayıp mum\' (cire perdue) yöntemiyle döküm yaparken izlediği adımların doğru sırası hangisidir?', 'Mum model, kalıp kaplama, mumun eritilip akıtılması, metal dökümü', ['Metal döküm, mum model, kalıp kaplama ve ardından mumun akıtılması', 'Kalıp kaplama, metal döküm, mum model, mumun eritilmesi', 'Mumun eritilmesi, mum model, metal döküm, kalıp kaplama'], 'Önce mumdan model yapılır, ısıya dayanıklı kalıp malzemesiyle kaplanır, ısıtılarak mum dışarı akıtılır; boşalan hacme erimiş metal dökülür.'),
  ('1886\'da bir New York kuyumcusu tarafından tanıtılan, altı tırnakla elmasın metal tabandan yukarı kaldırıldığı solitaire yüzük biçimi hangisidir?', 'Tiffany setting', ['Pavé setting', 'Kanal', 'Illusion'], 'Tırnaklar taşı bandın üstüne kaldırarak her yönden gelen ışığın elmasa ulaşmasını sağlar; bu nedenle taş çok parlak görünür.'),
  ('Elmas kesimlerinde \'brilliant\' kesim yaklaşık kaç faset (yüzey) içerir?', '57', ['12', '30', '99'], 'Modern yuvarlak brilliant kesimde üstte 33, altta 24 faset bulunur; kesim ışığı içeride tam yansıtarak elmasın parlamasını sağlar.'),
  ('Elmasın değerini belirleyen \'4C\' ölçütleri hangileridir?', 'Kesim, renk, berraklık ve karat', ['Kalınlık, renk, kimyasal yapı ve cilanın birleşimi', 'Kesit, kalite, kıta ve ağırlık', 'Kesim, kütle, kabuk ve cila'], '4C ölçütleri Cut (kesim), Color (renk), Clarity (berraklık) ve Carat (ağırlık) sözcüklerinin baş harfleridir ve elmasın değerini birlikte belirler.'),
  ('Yakut ve safirin kimyasal olarak aynı mineralin farklı renkli çeşitleri olması neyi anlatır?', 'İkisinin de korindon olması', ['İkisinin de beril olması ve içindeki krom miktarının farklı olması', 'İkisinin de kuvars olması', 'İkisinin de elmas olması'], 'Korindon (alüminyum oksit) kırmızı olduğunda yakut, diğer renklerde safir adını alır. Safir çoğunlukla mavi akla gelir ama pembe, sarı ve renksiz çeşitleri de vardır.'),
  ('İncinin madenî bir taş olmayıp organik bir mücevher sayılmasının nedeni nedir?', 'Bir yumuşakçanın salgıladığı sedefli kalsiyum karbonat katmanlarından oluşması', ['Volkanik kayaçların içindeki gaz boşluklarının mineralle dolması', 'Reçinenin fosilleşmesi', 'Hayvan dişinden yapılması'], 'İnci, midye ya da istiridye içinde yabancı bir maddenin etrafına sedef (nacre) salgılanmasıyla oluşur. Bu nedenle yumuşak ve asitlere karşı duyarlıdır.'),
  ('Mücevher yapımında mercanın hangi özelliği onu organik taşlar arasına sokar?', 'Deniz hayvanlarının kalsiyum karbonatlı iskeletlerinden oluşması', ['Magma içinde yüksek basınçla kristalleşmeleri ve elde sertleşmeleri', 'Fosil reçine olması', 'Metal oksidi olması'], 'Mercan, deniz polipleri tarafından oluşturulan bir iskelettir; Akdeniz\'in kırmızı mercanı yüzyıllardır tılsım ve süs olarak kullanılmıştır.'),
  ('Hindistan\'ın Golconda bölgesi, tarihte hangi mücevher taşıyla ünlüdür?', 'Çok saf, renksiz ve büyük elmaslar', ['Çok parlak yeşil renkli ve büyük zümrütler', 'İnciler', 'Kehribarlar'], 'Golconda elmasları, çoğu çok saf olup tarihin ünlü büyük taşlarının kaynağı olmuştur; Güney Afrika ve Brezilya yatakları bulunmadan önce Hindistan baş kaynaktı.'),
  ('Bir kuyumcu bir yüzüğün iç yüzünde \'750\' damgası görüyor. Bu damga ne anlama gelir?', 'Binde 750 saf altın içerdiğini, yani 18 ayar olduğunu', ['Binde 585 saf altın içerdiğini, yani 14 ayar olduğunu', 'Parçanın 750 gram olduğunu', 'Parçanın 750. üretim olduğunu'], 'Saf altın 24 ayardır; 18 ayar ise binde 750 saf altın içerir; damga bu saflığı güvence altına alır.'),
  ('Bir kuyumcu elinde pembe renkli, bakır içeriği yüksek bir altın alaşımı ve beyaz renkli, paladyum içeren bir alaşım var. Bu iki alaşımın rengi neden farklıdır?', 'Katılan metallerin altının sarı rengini farklı biçimde değiştirmesi', ['Altının oranının farklı olması ve parçaların farklı yoğunlukta döküldüğü', 'Işıktan etkilenmeleri', 'Taşların yansıması'], 'Bakır altına kırmızımsı, paladyum ve nikel ise beyazımsı bir ton verir; altın oranı aynı olsa bile alaşımın rengi katkıya göre değişir.'),
  ('Bulgaristan\'daki Varna Nekropolü\'nde bulunan altın nesneler, kuyumculuk tarihinde neden önemlidir?', 'İşlenmiş altının bilinen en eski örneklerinden olmaları', ['Kâğıt para gibi ödeme aracı olarak kullanılan ilk altın levhalar olmaları', 'Roma döneminden kalma olmaları', 'İlk elmas işçiliğini göstermeleri'], 'Varna\'daki mezarlardan çıkan altın nesneler MÖ 5. binyıla tarihlenir; Avrupa\'da bilinen en eski işlenmiş altın sayılırlar.'),
  ('Uşak Müzesi\'nde sergilenen ve bir dönem yurt dışına kaçırılıp 1993\'te iade edilen Karun Hazinesi hangi uygarlığa aittir?', 'Lidyalılara', ['Hititlere', 'Frigyalılara', 'Urartulara'], 'Karun Hazinesi, Lidya\'nın zengin kralı Kroisos\'un adıyla anılan MÖ 6. yüzyıl buluntusudur; Lidyalılar altınla ve ilk sikkelerle bilinir.'),
  ('Cartier\'nin 1904\'te havacı Alberto Santos-Dumont için tasarladığı yenilik nedir?', 'Cebe değil bileğe takılan saat', ['Platin kakmalı, gözün önüne takılan ilk elmas çerçeveli gözlük', 'Elmaslı pusula', 'Altın dolma kalem'], 'Santos-Dumont uçuş sırasında cep saatine bakamadığı için dostu Louis Cartier ona bilek saati yaptı; bu fikir sonradan yaygınlaştı.'),
  ('Van Cleef & Arpels\'in 1933\'te patentini aldığı \'Mystery Set\' (Gizemli Mıhlama) tekniğinin ayırt edici sonucu nedir?', 'Taşların yüzeyinde metalin görünmediği, taşlar arasında tırnak bulunmayan düz bir yüzey', ['Taşların tamamen havada asılı durduğu, hiçbir metal desteği olmayan bir yüzey', 'Taşların yalnız tek yönden görünmesi', 'Taşların renkli camla kaplanması'], 'Taşlar altlarındaki yivlere kızakla geçirilerek mıhlanır; yüzeyde yalnız taşlar görünür. Yöntem çok işçilik gerektirdiğinden pahalıdır.'),
  ('Kuyumculukta taşların arkasına yerleştirilen ince metal folyonun amacı nedir?', 'Taşın rengini ve parıltısını artırmak', ['Taşı daha ağır göstermek ve kuyumcuya satış sırasında ek ağırlık kazandırmak', 'Taşı erimekten korumak', 'Taşı sertleştirmek'], 'Eski mücevherlerde kuyumcular, taşın altına renkli folyo koyarak parlaklığı ve rengi artırırdı; bu yöntem özellikle 18. yüzyıla kadar yaygındı.'),
  ('Bir mücevher koleksiyoncusu, Art Deco döneminin geometrik yüzük örneğini ayırt etmek istiyor. Hangi özelliğe bakmalıdır?', 'Platin gövde, çok sayıda küçük elmas ve zıt renkli kare ya da baget kesim taşlar', ['Çok sayıda çiçek ve böcek motifli, saydam minelerle bezeli plique-à-jour parçalar', 'Yalnız kaba kesim kehribar', 'Elle kabartılmış altın yaprak'], 'Art Deco mücevher platin, baget kesim taşlar ve keskin simetri ile tanınır. Çiçek ve böcek ise Art Nouveau\'nun işaretleridir.'),
  ('Japon lakesinde nemli bir dolapta (\'muro\') bekletilerek kurutulmanın nedeni nedir?', 'Lakenin sertleşmesi için nem ve ılıklık gerektirmesi', ['Lakenin boyasının kuruma sırasında fazla ısınıp yanması ve rengini kaybetmesi', 'Lakenin soğukta büzülmesi', 'Lakenin buharlaşması'], 'Urushi sıradan boyalar gibi havada kurumaz; içindeki enzim nemli ve ılık ortamda çalışarak lakeyi sertleştirir.'),
  ('Japon kimono kuşağına bağlanıp ilaç kutusu (inro) ya da kese asmak için denge ağırlığı olarak kullanılan küçük oyma nesneye ne ad verilir?', 'Netsuke', ['Tsuba', 'Raden', 'Furoshiki'], 'Kimonoda cep olmadığından küçük eşyalar kuşağa asılır; netsuke fildişi ya da ahşaptan hayvan ve insan figürü olarak oyularak hem işlev hem sanat nesnesi hâline gelmiştir.'),
  ('Irak\'ın Musul kentinde 13. yüzyılda yapılan gümüş kakmalı pirinç kaplar, hangi teknikle ünlüdür?', 'Bakır alaşımı üzerine gümüş ve altın kakma', ['Cam yüzeye altın tozu serpilip fırında eritilerek sabitlenmesi', 'Seramik üzerine lüster', 'Ahşap üzerine sedef kakma'], 'Mosul ustaları pirinç kapların yüzeyine ince gümüş ve altın teller çakarak figürlü ve yazılı desenler oluşturdu; British Museum\'daki Blacas ibriği bunun ünlü örneğidir.'),
  ('Osmanlı\'da bakır ve çinko alaşımına cıvalı yaldız uygulanarak yapılan, kâse ve şamdanlarda görülen metal sanatına ne ad verilir?', 'Tombak', ['Kündekâri', 'Kalem işi', 'Telkâri'], 'Tombak, bakır-çinko alaşımına cıvayla altın yaldız kaplayarak elde edilir. Cıva buharı zararlı olduğundan bu yöntem sonradan terk edilmiştir.'),
  ('Bakır mutfak kaplarının içinin kalayla kaplanmasının (kalaylama) nedeni nedir?', 'Bakır tuzlarının yiyeceğe karışıp zehirlemesini önlemek', ['Kabın daha çabuk ısınmasını ve yemeğin altına yapışmamasını sağlamak', 'Kabı altın rengine boyamak', 'Kabın içini koklamak'], 'Asitli yiyecekler bakırla temas edince zehirli bakır tuzları oluşur; kalay tabakası yemekle bakır arasında koruyucu bir engel kurar.'),
  ('Kaşmir şallarından esinlenerek İskoçya\'da üretilen ve adını bir kasabadan alan, damla biçimli desene ne ad verilir?', 'Paisley', ['Chintz', 'Toile', 'Damask'], 'Paisley (boteh), Hint kökenli palmet motifidir; İskoçya\'daki Paisley kasabasında Jacquard tezgâhlarında taklit şallar dokunduğundan batıda bu adı almıştır.'),
  ('Altın ve gümüş iplikle yapılan yoğun nakışa, Hint ve İran geleneğinde ne ad verilir?', 'Zardozi', ['Bandhani', 'Sashiko', 'Kantha'], 'Zardozi, \'altın nakış\' anlamına gelir; metal teller, pul ve boncuklarla kumaşa kabartmalı nakış yapılır. Babür sarayında çok sevilmiştir.'),
  ('Floransa\'da Medici ailesinin desteklediği sert taş (pietra dura) panolarında en çok hangi motif görülür?', 'Çiçekler, kuşlar ve manzaralar', ['Yalnız geometrik çizgiler ve tekrarlanan kare desenler', 'Yalnız yazılar', 'Yalnız altın zeminler'], 'Floransa pietra durası, değerli ve yarı değerli taşlardan kesilmiş parçalarla çiçek, meyve ve manzara gibi doğal motifleri taklit eder.'),
  ('Gümüş eşyada kararmanın (patinanın) başlıca nedeni nedir?', 'Havadaki kükürt bileşikleriyle gümüş sülfür oluşması', ['Gümüşün havadaki nemle suda çözünüp yüzeyde ince bir tabaka bırakması', 'Gümüşün ışıkla beyazlaması', 'Gümüşün manyetik olması'], 'Gümüş, havadaki hidrojen sülfürle tepkimeye girip siyah gümüş sülfür tabakası oluşturur; bu yüzden gümüş eşya bakım gerektirir.'),
  ('Bir koleksiyoncu, bir bakır tabağın içinde yeşilimsi bir tabaka görüyor. Bu tabaka en olası hangi maddedir?', 'Bakır karbonat (yeşil pas)', ['Demir oksidi (kırmızı-kahverengi pas tabakası)', 'Gümüş sülfürü', 'Kalay oksidi'], 'Bakır havadaki nem ve karbondioksitle tepkimeye girerek yeşil bir tabaka oluşturur; Özgürlük Anıtı\'nın yeşil rengi de aynı nedenledir.'),
  ('Aesthetic Movement\'ın (\'Estetik Hareket\') ana felsefesini en iyi hangi söz özetler?', 'Sanat, bir ahlaki ya da toplumsal amaca değil güzelliğe hizmet eder', ['Sanatın toplumsal sınıfları kaldırmak için üretilmesi gerektiği', 'Sanat yalnız dinsel konuları işlemelidir', 'Sanat sadece makine ürünüdür'], '\'Sanat sanat içindir\' ilkesi, Oscar Wilde ve Whistler çevresinde güzelliğin kendinden değerli olduğunu savundu; mobilya, seramik ve duvar kâğıdına uygulandı.'),
  ('William Morris\'in 1859\'da Bexleyheath\'te mimar Philip Webb\'e yaptırdığı ve iç mekânını arkadaşlarıyla birlikte süslediği ev hangisidir?', 'Red House (Kırmızı Ev)', ['Hill House (Mackintosh\'un Helensburgh\'teki konutu)', 'Casa Milà', 'Villa Savoye'], 'Kırmızı tuğlalı ev, Arts and Crafts hareketinin başlangıcı sayılır; Morris\'in 1861\'de kurduğu firma bu ev deneyiminden doğdu.'),
  ('C. R. Ashbee\'nin 1888\'de Londra\'da kurup sonra Chipping Campden\'a taşıdığı zanaatkâr topluluğunun adı nedir?', 'Guild of Handicraft (El Sanatları Loncası)', ['Omega Workshops (Roger Fry\'ın Bloomsbury\'deki atölyesi)', 'Wiener Werkstätte', 'Deutscher Werkbund'], 'Ashbee, işçilerin ortak çalıştığı ve kâr paylaştığı bir atölye ideali kurdu; Arts and Crafts\'ın toplumsal yönünü yaşatmaya çalıştı.'),
  ('Mackintosh\'un Hill House için tasarladığı, sırtlığı çok yüksek ve dik hatlı sandalyenin başlıca özelliği nedir?', 'Yüksek, dar ve dikdörtgen ızgaralı sırtlık', ['Çelik borulu, hafif ve konsol biçimli gövdesi', 'Kıvrımlı rokoko ayaklar', 'Tek parça plastik kabuk'], 'Mackintosh\'un yüksek sırtlıklı sandalyesi (ladder-back), mekânda dikey vurgu yaratan heykelsi bir ögedir; Glasgow Okulu\'nun simgesidir.'),
  ('\'Art Déco\' adının türediği 1925 sergisinin adı nedir?', 'Paris Modern Dekoratif ve Endüstriyel Sanatlar Uluslararası Sergisi', ['Londra Büyük Sergisi', 'Weimar Bauhaus Sergisi', 'New York Armory Show'], 'Sergi, Paris\'te 1925\'te açıldı ve adını \'Arts Décoratifs\'ten alan akım, 1960\'larda \'Art Déco\' olarak adlandırıldı.'),
  ('Henry van de Velde\'nin tasarımcı kimliği, Art Nouveau\'da hangi yeni anlayışı temsil eder?', 'Süslemeyi yapıdan ayırmayıp çizgiyi dinamik bir enerji olarak kullanması', ['Süslemeyi tamamen reddedip yapıyı hiçbir çizgi kullanmadan bırakması', 'Yalnız tarihî üslupları kopyalaması', 'Yalnız taş heykeltıraşlık yapması'], 'Van de Velde, çizginin kendi gücü olduğunu savundu; mimariden mobilyaya kadar her şeyi tek çizgiyle bütünleştirdi. 1902\'de Weimar\'da yönettiği okul, Bauhaus\'un öncülüdür.'),
  ('Christopher Dresser\'in Victoria dönemi tasarımındaki yeri nasıl tanımlanır?', 'Sanayi için çalışan ilk bağımsız endüstri tasarımcılarından biri', ['Yalnız gotik katedrallerin vitraylarını yapan ve fabrikalarla hiç çalışmayan bir usta', 'Bir seramik fırın ustası', 'Kraliyet ressamı'], 'Dresser, Japon sanatından ilham alan metal eşya, seramik ve tekstil tasarımları üretti; fabrikalarla çalışan serbest tasarımcı olarak modern endüstri tasarımının öncüsü sayılır.'),
  ('1851 Büyük Sergi\'nin kurulduğu, cam ve demirden yapılmış binada sergilenen ürünlerin tasarım kalitesi hakkında eleştirmenlerin görüşü ne olmuştur?', 'Üretim bolluğu karşısında zevksiz süsleme eleştirilmiş, tasarım reformu çağrıları artmıştır', ['Her ürünün kusursuz tasarım örneği sayılması ve eleştirinin yok olması', 'Makine üretimi yasaklanmıştır', 'Süsleme tamamen bırakılmıştır'], 'Sergideki aşırı süslü makine yapımı eşyalar eleştirilince Cole ve Jones gibi isimler tasarım reformu başlattı; bu tartışmalar Arts and Crafts\'ın zeminini hazırladı.'),
  ('Bir yapının ya da mobilyanın yüzeyinde hükümdarın adının ya da bir yazının yazıldığı, çerçevesi süslü oval veya yuvarlak alana ne ad verilir?', 'Kartuş (cartouche)', ['Meander (dik açılı kıvrımlardan oluşan şerit bezeme)', 'Putto', 'Akant'], 'Kartuş, hem Mısır\'da firavun adının yazıldığı oval çerçevedir hem de Barok ve Rokoko\'da yazı ya da arma için süslü çerçevedir.'),
  ('Antik Roma\'da Nero\'nun Altın Saray\'ı (Domus Aurea) kazıldıktan sonra Rönesans sanatçılarını etkileyen, hayvan, insan ve bitkilerin birbirine karıştığı fantastik süsleme türü hangisidir?', 'Grotesk', ['Chinoiserie', 'Rocaille', 'Cartouche'], 'Mağara (grotta) gibi yeraltı odalarda bulunduğu için \'grotesk\' adını alan bu süsleme, Raffaello ve öğrencilerinin Vatikan Locaları\'nda yeniden yorumlanmıştır.'),
  ('Rokoko adının kaynağı olan \'rocaille\' süslemesi neyi andırır?', 'Kabuk ve kaya biçimli kıvrımlı süsleri', ['Sivri uçlu, dikey vurgulu gotik kemer ve sivri pencere biçimlerini', 'Düz geometrik çizgileri', 'Sütun başlıklarını'], '\'Rocaille\', bahçe mağaralarında kullanılan kaya ve kabuk süslerinden türemiştir; 18. yüzyılda asimetrik kıvrımlı süsleme anlamını kazanmıştır.'),
  ('Fransız saraylarında zeminlere uygulanan, ahşap parçaların balık kılçığı ya da dama düzeninde döşendiği döşeme türüne ne ad verilir?', 'Parke (parquet)', ['Marküteri (renkli ahşap parçalarla resim yapma işçiliği)', 'Kaplama', 'Boiserie'], 'Parke, küçük ahşap parçaların geometrik düzende döşenmesiyle elde edilir; 17. yüzyılda Versailles\'da özel bir işçilik hâline gelmiştir.'),
  ('İngiltere\'de 17. yüzyıl mobilyasına \'Meşe Çağı\' (Age of Oak) denilmesinin nedeni nedir?', 'O dönemde yaygın mobilya malzemesinin meşe olması', ['Meşe ağacının tüm ormanlardan kesilip ihraç edilmesinin yasaklanmış olması', 'Meşenin porselenle karıştırılması', 'Meşe ormanlarının tamamen yok olması'], 'Tudor-Jacobean döneminde yapılan ağır, oymalı dolap ve sandıklar neredeyse tamamen meşeydi; sonra ceviz ve maun öne çıktı.'),
  ('18. yüzyıl ortasında İngiliz mobilyasında maun kullanımının yaygınlaşmasının nedeni neydi?', 'Batı Hint Adaları\'ndan gelen maunun sert, kolay işlenir ve geniş tahtalar verebilmesi', ['Maunun çok ucuz olması ve ağır vergilerden muaf tutulması', 'Meşenin hiç kalmaması', 'Cevizin yasaklanması'], 'Maun, ince oyma ve büyük kapaklı masalara uygun olduğundan Chippendale döneminde en değerli malzeme olmuştur.'),
  ('Mobilyada \'abanoz\' ağacı, hangi özelliğiyle değer görmüştür?', 'Çok sert ve siyah rengiyle', ['Çok hafif ve beyaz rengiyle', 'Kokulu ve yumuşak olmasıyla', 'Kırmızı damarlı olmasıyla'], 'Abanoz çok yoğun, siyah ve cilayı iyi tutar; Louis XIV döneminde bu ağacı kullanan ustalara \'ébéniste\' adı da buradan verilmiştir.'),
  ('Fransızca \'ébéniste\' (kaplamacı ebeniste) sözcüğü hangi ağaç adından türemiştir?', 'Abanoz (ébène)', ['Maun (kırmızımsı kahverengi, kolay işlenen tropik ağaç)', 'Ceviz', 'Meşe'], '17. yüzyıl Fransa\'sında egzotik abanozla kaplama yapan ustalara \'ébéniste\' denmiş; sözcük sonradan bütün kaplamacı mobilya ustalarını kapsamıştır.'),
  ('Antik Mısır\'da firavun Tutankamon\'un tahtı hangi malzemelerle bezelidir?', 'Altın varak, gümüş, renkli cam ve değerli taş kakma', ['Yalnızca çiviyle birleştirilmiş çam ağacı ve düz bakır levhalar', 'Yalnız demir', 'Yalnız taş'], 'Tutankamon\'un altın tahtı ahşap üzerine altın ve gümüş yaprak, cam ve taş kakmalarla süslü; tahtın arka yüzünde Aton\'un ışıklarından esinli bir sahne bulunur.'),
  ('Romalı Cosmati ustalarının 12-13. yüzyılda kilise zeminlerinde uyguladığı bezemenin özelliği nedir?', 'Renkli mermer ve cam parçalarla geometrik mozaik desenler', ['Yalnızca beyaz mermerden kesilmiş geniş döşeme levhaları ve süssüz yüzey', 'Yalnız ahşap parke', 'Yalnız bronz plaka'], 'Cosmati işi, çok renkli mermer ve cam parçalarından döşenmiş dairesel ve çapraz geometrik zeminlerdir; Roma kiliselerinde görülür.'),
  ('Bir iç mimar, ışığı yansıtarak küçük bir odayı büyük gösterecek bir çözüm arıyor. Versailles Aynalar Galerisi örneğinden hangi ilkeyi alabilir?', 'Karşılıklı aynalarla ışığı yansıtıp derinlik yanılsaması yaratmayı', ['Pencereleri kapatıp odayı karanlık ve daha yoğun renkli göstermeyi', 'Koyu renkli perdeleri çoğaltmayı', 'Tavanı alçaltmayı'], 'Aynalar ışığı ve mekânı katlayarak odayı daha geniş ve aydınlık gösterir; bu ilke Barok saray mimarisinden bugüne kullanılır.'),
  ('İçinde 12 gram saf altın bulunan 18 ayar bir bileziğin toplam ağırlığı kaç gramdır?', '16 gram', ['18 gram', '14 gram', '20 gram'], '18 ayar altında saf altın oranı 3/4\'tür. Toplam ağırlık = 12 ÷ 0,75 = 16 gramdır.'),
  ('80 gram sterlin gümüşten yapılmış bir tepsinin içindeki saf gümüş miktarı kaç gramdır?', '74 gram', ['72 gram', '68 gram', '78 gram'], 'Sterlin gümüş binde 925 saf gümüş içerir. 80 × 0,925 = 74 gramdır.'),
  ('Bir kuyumcu 6 gram saf altına 2 gram bakır katarak alaşım hazırlıyor. Alaşımın ayarı kaçtır?', '18 ayar', ['14 ayar', '22 ayar', '12 ayar'], 'Toplam ağırlık 8 gramdır; altın oranı 6/8 = 0,75. 0,75 × 24 = 18 ayar bulunur.'),
  ('Kurutulup pişirildiğinde ilk boyuna göre toplam yüzde 12 küçülen bir kil vazonun pişmiş hâlde 22 cm olması isteniyorsa, ilk şekillendirmede kaç cm yüksekliğinde yapılmalıdır?', '25 cm', ['24 cm', '26 cm', '23 cm'], 'Pişmiş boy ilk boyun %88\'idir. İlk boy = 22 ÷ 0,88 = 25 cm bulunur; yüzde küçülme ilk ölçüden hesaplanır.'),
  ('Bir kumaşın inç karesinde 120 çözgü ve 80 atkı ipliği varsa bu kumaşın iplik sayısı (thread count) kaçtır?', '200', ['120', '9600', '40'], 'Iplik sayısı, inç karedeki çözgü ve atkı ipliklerinin toplamıdır. 120 + 80 = 200 bulunur; çarpılmaz.'),
  ('Kurşun kristal sayılabilmesi için cam içindeki kurşun oksit oranının en az yüzde 24 olması gerekiyorsa, 10 kg kurşun kristalde en az kaç kilogram kurşun oksit bulunur?', '2,4 kg', ['24 kg', '1,2 kg', '0,24 kg'], '10 kg\'ın %24\'ü, 10 × 0,24 = 2,4 kg eder. Bu oran, kristal ile sıradan camı ayıran hukukî ve ticari ölçütlerden biridir.'),
  ('İngiliz çömlekçi Bernard Leach\'in 1920\'de Shoji Hamada ile birlikte kurduğu ve \'Doğu-Batı\' sentezini yürüttüğü atölye hangi kasabadadır?', 'St Ives', ['Stoke-on-Trent', 'Mashiko', 'Vallauris'], 'Leach, Japonya\'da edindiği çömlekçilik anlayışını St Ives\'te kurduğu atölyede İngiliz çanak çömlek geleneğiyle birleştirdi; stüdyo çömlekçiliğin kurucusu sayılır.'),
  ('Bir seramikçi, vazonun sırının pişirimden sonra kabarcıklı ve düzensiz olduğunu görüyor. Bu sorunun nedeni nedir?', 'Sırın fırında gerektiğinden düşük ya da yüksek ısıda pişmesi ve gazın çıkamaması', ['Kilin çok beyaz olması ve hamura fazla su katılması', 'Fırçanın yumuşak olması', 'Fırının soğuk bırakılması'], 'Sır doğru ısıda erimezse gaz kabarcıkları yüzeye çıkıp sırın içinde donar; kabarcıklı yüzey olur.'),
  ('Orta Çağ vitray ustalarının 14. yüzyıl başında cam yüzeyi sarıya boyamak için bulduğu yöntem nedir?', 'Gümüş bileşiği sürülüp fırınlanması', ['Altın tozunun cama serpilip fırınlanarak yaldızlanması', 'Kükürtlü cıva sürülmesi', 'Bakır levhanın eritilmesi'], 'Gümüş sarısı, camın yüzeyine sürülen gümüş tuzunun ısıyla nüfuz etmesiyle parlak sarı bir ton verir; böylece aynı parçada iki renk elde edilebilirdi.'),
  ('Gerhard Richter\'in 2007\'de Köln Katedrali\'nin güney transept penceresi için yaptığı çalışmanın ayırt edici özelliği nedir?', 'Binlerce renkli kare cam parçasının rastlantıya dayalı bir düzenle dizilmesi', ['Kutsal kitap sahnelerini klasik biçimde anlatan figürlü pencereler', 'Tamamen şeffaf pencere', 'Siyah-beyaz fotoğraf baskısı'], 'Richter, 72 renk ve yaklaşık 11.500 kare cam parçasını rastlantısal bir şemayla dizerek geleneksel figüratif vitrayın yerine soyut bir ışık alanı kurdu.'),
  ('Orta Çağ vitraylarının yüzyıllar sonra bile renklerini koruyabilmesinin başlıca nedeni nedir?', 'Rengin camın kitlesine metal oksitlerle katılması, yüzeye boyanmaması', ['Boyanın dış yüzeye sonradan fırçayla sürülüp fırınlanması', 'Camın hiç ısıtılmaması', 'Camın yağlı boyayla kaplanması'], 'Çoğu Orta Çağ vitrayı, rengi cam hamuruyla birlikte eritilerek elde edilir (pot metal); bu renk cam kırılana dek kaybolmaz.'),
  ('Katedrallerde duvar yüzeyi azalıp pencereler büyüdükçe vitray hangi işlevi üstlenmiştir?', 'Okuma yazma bilmeyenlere kutsal anlatıları göstermek ve içeriye renkli ışık vermek', ['Yalnızca soğuğu ve rüzgârı engelleyip yapının sıcaklığını korumak', 'Sadece güvenliği sağlamak', 'Havalandırmayı artırmak'], 'Vitray hem kutsal öyküleri görsel biçimde anlatır hem de ışığı manevi bir atmosferde süzer; bu yüzden Gotik\'te çok önem kazanmıştır.'),
  ('Orta Çağ\'da Ypres, Gent ve Brugge gibi Flaman kentlerini zenginleştiren üretim kolu hangisiydi?', 'İngiliz yününden dokunan kumaş', ['Çin ipeğini Avrupa\'ya taşıyıp kumaşa dönüştürme ticareti', 'Cam üfleme', 'Altın işlemeciliği'], 'Flanders\'ın dokumacıları İngiltere\'den ithal ettikleri yünü işleyip Avrupa\'nın dört bir yanına kumaş sattılar; Ypres\'in Kumaş Salonu bu zenginliğin simgesidir.'),
  ('Japon kimonosunun düz kumaş şeritlerinden kesilip T biçimli dikilmesinin sonucu nedir?', 'Kumaş israf edilmeden sökülüp yeniden kullanılabilir', ['Giysi dikişsiz biçimde tek parça halinde dokunur ve kesilmez', 'Kumaşın kesilmesi yasaktır', 'Giysi her zaman tek renklidir'], 'Geleneksel kimono düz dikdörtgen parçalardan yapıldığı için sökülüp yıkanabilir ve yeniden dikilebilir; bu kumaş tasarrufu sağlar.'),
  ('Osmanlı sultan kaftanlarında sık görülen, üç top ile altında iki dalgalı çizgi biçimindeki motifin adı nedir?', 'Çintemani', ['Hatayi', 'Rumi', 'Penç'], 'Çintemani, kökeni Çin-Hint kaynaklı olduğu düşünülen üçlü benekler ve dalgalı çizgilerden oluşur; 15-17. yüzyıl saray kumaşlarında yaygındır.'),
  ('Bir müzede cam yüzeyinde ince kahverengi çizgilerle yapılmış bir yüz ve çevresinde kurşun çıtalar görülüyor. Bu çizgilerin yapımı hangi işlemle gerçekleşmiştir?', 'Gri tonlu boyanın cama sürülüp fırınlanması', ['Camın asitle oyulup üzerine renkli cam parçalarının sonradan kaynaştırılması', 'Camın boyanmadan üflenmesi', 'Camın seramik üstüne yapıştırılması'], 'Çizgi ve gölgeler, cam üzerine grisaille boyayla çizilip fırında sabitlenir; kurşun çıta sınırları ise ana renk alanlarını ayırır.'),
  ('Kokichi Mikimoto\'nun 1893\'te Japonya\'da başardığı gelişme nedir?', 'İstiridyelerde kontrollü biçimde kültür incisi üretimi', ['Elmasın laboratuvarda yüksek basınçla yapay biçimde üretilmesi ve ticarileşmesi', 'Altının sudan ayrılması', 'Mercanın cilalanması'], 'Mikimoto, istiridyenin içine bir çekirdek yerleştirerek incinin kontrollü oluşmasını sağladı; doğal inci pahalı bir lüks iken kültür incisi bu piyasayı genişletti.'),
  ('Mücevher taşlarında kabaşon kesim, hangi biçimde bir kesimdir?', 'Yüzeyi yuvarlatılmış, fasetsiz ve kubbeli kesim', ['Çok sayıda küçük yüzeyli, ışığı içte yansıtan parlak brilliant kesim', 'Dikdörtgen baget kesim', 'Elmas biçimli kesim'], 'Kabaşonda taş, fasetlenmeden kubbe biçiminde cilalanır; opak ya da yıldız etkisi veren taşlar için uygundur, çünkü ışık içeride zaten yansıtılmaz.'),
  ('Zümrütlerde sıkça uygulanan, köşeleri kesilmiş dikdörtgen basamaklı kesim türü hangisidir?', 'Zümrüt (emerald) kesim', ['Brilliant kesim', 'Marquise kesim', 'Kabaşon kesim'], 'Basamaklı kesim, zümrütün kırılgan yapısını köşe darbelerinden korur ve iç kısmını gösterir; bu yüzden bu kesim adını zümrütten almıştır.'),
  ('İnci takılarının zamanla donuklaşmasını hızlandıran ortak ev etkenleri hangileridir?', 'Kozmetik, parfüm ve asidik terle temas', ['Karanlık ve kuru bir kutuda uzun süre bekletilmesi ve nemden korunması', 'Kuru bir kutuda saklanması', 'Soğuk suyla ıslatılması'], 'İnci kalsiyum karbonattan olduğundan asit ve kimyasallardan zarar görür; takıldıktan sonra yumuşak bezle silmek önerilir.'),
  ('Işığın bir mücevher taşına girip dalga boyuna göre ayrışması ve parıltı vermesi hangi olayla ilişkilidir?', 'Dispersiyon (ışığın renklere ayrılması)', ['Radyoaktivite (çekirdeklerin kendiliğinden ışıma yapması)', 'Manyetizma', 'Elektrolit etkisi'], 'Dispersiyon, elmasa \'fire\' (renkli parıltı) verir; yüksek kırılma indisiyle birlikte elmasın cazibesinin temel nedenidir.'),
  ('Kuyumculukta lehimin, birleştirilen parçaların erime sıcaklığından düşük ısıda eriyen alaşım olması neden gereklidir?', 'Lehim erirken ana parçaların erimemesi için', ['Lehimin parlak görünmesi ve renk bakımından ana metale uyması için', 'Lehimin daha ağır olması için', 'Lehimin renk değiştirmesi için'], 'Lehim alaşımı, birleştirilen altın ya da gümüşten daha düşük sıcaklıkta eriyecek biçimde ayarlanır; böylece parçalar şeklini korur.'),
  ('Kuyumculukta ince tel çekme işleminde metalin hangi özelliği esastır?', 'Tel hâline getirilebilme', ['Mıknatısa çekilebilir olması ve çelik kadar sert olması', 'Cam gibi kırılgan olması', 'Suda çözünmesi'], 'Altın, gümüş ve bakır sünek metallerdir; delikli çekme tahtasından birkaç kez geçirilerek incelip istenen kalınlığa gelir. Telkâri ve filigran bu işe dayanır.'),
  ('Guilloché tekniğinde metal yüzeyine ne yapılır?', 'Makine ile ince, dalgalı ve geometrik çizgi desenleri oyulur', ['Boncuk dizilerek metalin yüzeyinde ince kabartmalı dizi oluşturulur', 'Çok renkli mine sürülür', 'Metal tamamen eritilir'], 'Guilloché desenleri özel dişli makinelerle metale işlenir; ardından saydam mine ile kaplandığında ışık altında parıldar.'),
  ('Bir kuyumcu eski bir yüzüğün taşının cam olup olmadığını anlamak için hangi basit gözleme dayanabilir?', 'Taşın sertliği, içindeki küçük kabarcıklar ve parıltının derinliği', ['Taşın kutuda durması, kutunun markası ve fiyat etiketindeki yazı', 'Taşın fiyat etiketi', 'Yüzüğün ağırlığı'], 'Camda sıklıkla yuvarlak hava kabarcıkları ve çizilebilir yüzey görülür; gerçek taşlar ise daha sert ve parıltılı olup içinde farklı kalıntılar taşıyabilir.'),
  ('Bir kuyumcu zümrüt içindeki küçük çatlaklara \'jardin\' (bahçe) adını veriyor. Bu ad neden kullanılır?', 'Taşın içindeki doğal kusurların yeşil bir bahçeyi andırması', ['Zümrütlerin bahçelerde bulunması ve yeşil otlarla çevrili olması', 'Çatlakların kuyumcu bahçesinde açılması', 'Çatlakların altınla doldurulması'], 'Zümrütlerde iç çatlak ve kalıntılar çok yaygındır; kuyumcular bunları \'jardin\' diye adlandırır ve çoğu zaman taşın doğal olduğunun kanıtı sayar.'),
  ('Osmanlı\'da altın işleme ve değerli maden tartımında kullanılan \'miskal\' hangi anlamı taşır?', 'Altın ve kıymetli maddelerin tartımında kullanılan ağırlık ölçüsü', ['Mücevher yüzeylerine uygulanan, ince bir mine kaplama türü', 'Bir çeşit emaye', 'Bir kakma tekniği'], 'Miskal, Osmanlı\'da mücevher ve altın için kullanılan ağırlık birimiydi (yaklaşık 4,8 gram); mücevher, parfüm ve baharat tartımında yaygındı.'),
  ('İplik eğirmede kullanılan, bir çubuğa takılan ağırlıkla dönen ve elde tutulan en eski alete ne ad verilir?', 'El iğ', ['Jakar', 'Tarak', 'Mekik'], 'El iğ ya da düşen iğ (drop spindle), lif demetini bükerek ipliğe dönüştürür; dönen ağırlığın momentumu bükülmeyi sağlar. Binlerce yıldır kullanılmaktadır.'),
  ('Keçenin dokunarak değil de başka bir yöntemle yapıldığı söylenir. Keçe yapımında lifler hangi etkilerle birbirine kenetlenir?', 'Nem, ısı ve baskıyla lif pullarının birbirine kilitlenmesiyle', ['İplik bükülüp birbirine sarılarak ve örgü yapılarak', 'Lifler zamkla yapıştırılıp preslenerek ve kurutularak', 'Lifler iğneyle delinip kumaş katmanları dikilerek'], 'Yün lifinin yüzeyindeki pullar ıslak ve sıcak ortamda sürtünce birbirine geçer ve dokumasız bir kumaş oluşturur.'),
  ('Pamuk, keten ve yün liflerinin yanma sırasında nasıl davrandığı, gerçek liflerin tanınmasında kullanılan basit testlerden biridir. Yün yandığında hangi koku yayılır?', 'Yanmış saç ya da tüy kokusu', ['Yanmış kâğıt ya da yanmış odun kokusu', 'Erimiş plastik ve naylon kokusu', 'Hiç koku yayılmaz'], 'Yün, protein lifidir; yandığında saç yanması gibi kokar. Pamuk ve keten ise selülozdur; yanmış kâğıt kokusu çıkarır.'),
  ('Fransız sanatçı Jean Lurçat\'ın 20. yüzyıl ortasında gobelen sanatına katkısı nedir?', 'Gobelenin yenilenip sınırlı renk paletiyle çağdaş sanat dili kazanması', ['Gobelenin tamamen bırakılıp yerine duvar resminin geçmesi', 'Gobelenin yalnızca altın ve gümüş iplikle yapılması', 'Gobelenin sentetik boyayla basılması'], 'Lurçat, Aubusson atölyelerinde numaralandırılmış sınırlı renklerle çalışarak dokumacının yorumunu azalttı ve gobeleni çağdaş sanat düzeyinde yeniden canlandırdı.'),
  ('Tekstil sanatında \'lif sanatı\' (fiber art) akımının 1960\'larda yükselmesinin başlıca nedeni nedir?', 'Zanaat sayılan dokuma ve nakışın güzel sanat olarak kabul görmeyi talep etmesi', ['Resmin ve heykelin tamamen terk edilip yerine tekstil gelmesi', 'Sentetik liflerin ucuzlayıp el dokumacılığını bitirmesi', 'Yünün yasaklanması'], 'Lif sanatçıları dokuma ve nakışı resim ve heykel gibi sanat değeri taşıyan dallar olarak savundu; geleneksel zanaat-sanat ayrımını sorguladılar.'),
  ('Dokumada atkı ipliğinin çözgü aralarından geçirilmesinde kullanılan, iki ucu sivri, içi iplik makaralı alet hangisidir?', 'Mekik', ['Kirkit', 'Tarak', 'Gergi'], 'Mekik, atkı ipliğini taşıyıp çözgü arasından geçirir. Kay\'ın uçan mekiği mekik hareketini mekanikleştirmiştir.'),
  ('Ipek ipliğinin sağlam ve parlak olması, hangi lif yapısıyla ilişkilidir?', 'Uzun, sürekli ve pürüzsüz protein lifleri', ['Kısa, kıvrık ve bitkisel selüloz esaslı lifler', 'Çok kısa, kılcal ve gözenekli hayvan tüyü lifleri', 'Metal teller'], 'İpek böceği tek bir kozayı sürekli iplikle örer; bu uzun, ince ve düzgün yapı ipeğe parlaklık ve dayanım verir.'),
  ('Kenevir lifinin tarihte halat, yelken ve çuval yapımında yaygın kullanılmasının nedeni nedir?', 'Çok dayanıklı ve nemli ortamlara uygun olması', ['Çok yumuşak, parlak ve ısıyı iyi yalıtan bir lif olması', 'Çok ince, saydam ve buruşmaya karşı dayanıksız olması', 'Kolayca erimesi'], 'Kenevir lifi güçlü, ağır yüklere dayanıklı ve nemde bozulmayan bir bitkisel liftir; gemi donanmasında vazgeçilmezdi.'),
  ('Likra (elastan) ilk olarak hangi özelliğiyle giyim sanayisini değiştirmiştir?', 'Çok esnek olup eski formuna dönmesi', ['Çok sert ve eğilmez olup kırılgan davranması', 'Boyayı hiç tutmaması ve her zaman beyaz kalması', 'Su geçirmemesi'], 'Elastan lifi kendi boyunun çok katı gerilip eski haline döner; dar ve rahat giysilerin yapımını kolaylaştırdı.'),
  ('Pamuklu kumaşların yün ya da ipeğe göre daha kolay buruşmasının başlıca nedeni nedir?', 'Selüloz liflerinin esnekliğinin düşük olması', ['Pamuğun yüksek ısıda bile hiçbir zaman terlememesi', 'Pamuk liflerinin çok parlak olması ve ışığı yansıtması', 'Pamuğun metal içermesi'], 'Selüloz liflerin hidrojen bağları kıvrımda kalıcılaşır; yün lifinde ise kıvrım ve elastik yapı buruşmayı azaltır.'),
  ('Doğal lif ve sentetik lif karışımlı bir kumaşın tek başına doğal lifli kumaşa göre sağladığı pratik üstünlük nedir?', 'Dayanıklılık ve buruşmazlığın artması', ['Çok yüksek maliyet ve üretim zorluğu', 'Hiçbir zaman lekelenmemesi ve her yıkamada çekmesi', 'Hiç lekelenmemesi'], 'Polyester gibi sentetik lifler karışımda mukavemet ve buruşma direnci verir; doğal lifler ise nefes alabilirlik sağlar.'),
  ('Lif sanatında \'makrome\' tekniği nasıl yapılır?', 'İpliklerin düğümlenerek örülmesiyle', ['Kumaşın üzerine kalıpla boya basılarak ve fırınlanarak', 'Lif demetlerinin pişirilip dövülerek birbirine kenetlenmesiyle', 'Cam tozunun pişirilmesiyle'], 'Makrome, iplik demetlerinin çeşitli düğümlerle birbirine bağlanmasıyla yapılan, dokuma tezgâhı gerektirmeyen bir süsleme tekniğidir.'),
  ('Zincir dikişle nakışın başlıca özelliği nedir?', 'Birbirine geçen ilmeklerin zincir gibi dizilmesi', ['Düz tek çizgi hâlinde ve kopmadan ilerleyen koşu dikiş', 'Düğüm atılarak yüzeyde küçük kabarık noktalar oluşturan dikiş', 'Kumaşın kesilmesi'], 'Zincir dikişte her ilmek bir öncekinin içinden geçerek zincir halkaları oluşturur; çizgi ve dolgu için yaygındır.'),
  ('Kumaş boyamada \'banyo oranı\' ve ısının önemi neden büyüktür?', 'Boyanın liflere eşit işlemesi ve tutunması için', ['Kumaşın boyanırken kısalıp çekmesi için', 'Kumaşın boyadan sonra hemen kuruyup sertleşmesi için', 'Kumaşın kuruması için'], 'Boya molekülleri belirli ısıda ve oranda liflere nüfuz eder; kontrolsüz koşullar lekeli ve düzensiz renk verir.'),
  ('Bir kumaş, güneşte uzun süre kaldığında rengi solmuşsa bu kumaşın boyası hakkında ne söylenebilir?', 'Boyanın ışığa dayanıklılığının düşük olduğu', ['Boyanın hiç kullanılmadığı, kumaşın doğal renkte kaldığı', 'Boyanın ışığa karşı çok dayanıklı olduğu', 'Boyanın yalnızca kuru temizlemeyle çıktığı'], 'Işık haslığı, boyanın güneşe karşı direncini ifade eder; düşük haslık morötesi ışınlarla renk kaybına yol açar.'),
  ('Bir dokumacı, çözgü ipliklerini tezgâha gererken fazla gevşek bırakıyor. Kumaşta hangi sorun ortaya çıkar?', 'Kumaşın düzensiz sıklıkta ve dalgalı olması', ['Kumaşın çok parlak ve fazla sıkı olması', 'Kumaşın çok sert ve gerilimsiz olması', 'Kumaşın hiç dokunmaması'], 'Gevşek çözgüde atkı düzgün sıkılamaz; yüzey dalgalanır, kumaş eşit olmaz. Çözgü gerginliği düzgün kumaşın temel şartıdır.'),
  ('Bir butik sahibi aynı desenli ipek ve pamuklu eşarbı karşılaştırıyor. İpek eşarbın pamuğa göre ışığı yansıtma bakımından farkı nedir?', 'İpek lifi daha pürüzsüz olduğundan daha çok parlar', ['Pamuk lifi daha düzgün olduğundan daha çok parlar', 'İkisi de aynı parlaklıktadır; fark yalnızca fiyattadır', 'Fark tamamen boyadan kaynaklanır'], 'İpek lifinin düzgün, uzun ve üçgen kesitli yapısı ışığı yansıtarak doğal parlaklık verir; pamuk lifi ise kıvrımlı ve mat yapıdadır.'),
  ('Bir müze görevlisi, bir ipek kumaşı neden doğrudan güneş ışığından ve nemden korur?', 'İpek lifinin ışık ve nemde bozulup zayıflaması nedeniyle', ['İpek lifinin yüksek ısıda eriyip metalle tepkimeye girmesi nedeniyle', 'İpeğin kurşun içermesi ve çevreye zararlı gaz salması nedeniyle', 'İpeğin camla tepkimesi nedeniyle'], 'İpek protein lifi olduğundan morötesi ışınlar ve nem molekülünü zayıflatır; tarihî tekstiller bu yüzden loş ışıkta ve kontrollü nemde saklanır.'),
  ('Eski pencere camlarında zamanla mora dönen bir tonun görülmesi hangi katkı maddesinin ışıkla tepkimesinden kaynaklanır?', 'Mangan (rengi giderici olarak katılan)', ['Altın klorür (cam hamuruna kırmızı ton veren bileşik)', 'Kobalt oksit', 'Kalay oksit'], 'Cam ustaları yeşil demir tonunu gidermek için manganez katardı; morötesi ışık mangan bileşiğini yükseltgeyerek camı zamanla morumsu bir tona çevirir.'),
  ('Fransa\'da Colbert\'in 1665\'te kraliyet ayna manufakturasını kurmasının amacı neydi?', 'Venedik\'in ayna tekelini kırıp aynayı ülke içinde üretmek', ['Venedik aynalarının ithalatını artırıp yerel üretimi tamamen bırakmak', 'Aynaların kullanımını saray dışında yasaklayıp üretimi durdurmak', 'Gobelen yapımını durdurmak'], 'Colbert, Venedik ayna ustalarını getirterek kraliyet ayna manufakturasını kurdurdu; bu atölye sonradan Saint-Gobain adıyla anıldı. Versailles Aynalar Galerisi\'ndeki aynalar bu tesisin ürünüdür.'),
  ('17. yüzyıl Hollanda\'sında kadeh yüzeyine elmas uçlu iğneyle nokta nokta desen işleme tekniğine ne ad verilir?', 'Nokta gravürü (stipple engraving)', ['Asitle dağlama (hidroflorik asitle yüzeyin oyulması)', 'Katmanlı oyma (renkli tabakaların kesilerek desen elde edilmesi)', 'Kum püskürtme'], 'İnce nokta kümeleriyle gölgeli desen oluşturulur; teknik 17.-18. yüzyıl Hollanda\'sında çok sevilmiştir.'),
  ('Stanislav Libenský ve Jaroslava Brychtová\'nın Çekoslovak cam sanatına katkısı nedir?', 'Büyük ölçekli kalıpta dökülmüş cam heykelleri', ['Cam üfleme borusunun icadı ve Roma çağında yaygınlaşması', 'Vitray restorasyonunda kullanılan kurşun çıta teknikleri', 'Cam ayna üretimi'], 'Çift, kiln-cast cam heykeller ve mimari ölçekli cam kompozisyonlarıyla camı heykel malzemesi olarak yücelttiler.'),
  ('Cam kaba çok kısa sürede su soğuk dökülünce çatlıyorsa bunun nedeni nedir?', 'Cam yüzeyinin ani ısı değişimiyle farklı genleşmesi', ['Camın çok yumuşak olup soğuk suda bile yumuşaması', 'Suyun camı kimyasal olarak eritip incelmesine neden olması', 'Camın manyetik olması'], 'Sıcak cam hızla soğuyunca yüzey ile iç farklı hızda büzülür; oluşan gerilim camı çatlatır. Bu \'ısıl şok\' olayıdır.'),
  ('Pencere camının boyanmadan yeşilimsi görünmesi, camın hangi özelliğine dayanır?', 'Kumda bulunan demir safsızlıklarına', ['Camın içine katılan kobalt oksidin yeşile dönmesi', 'Camın kurşun içermesi ve kurşunun yeşil oksit oluşturması', 'Camın bakırla kaplanmasına'], 'Düşük maliyetli camda kumdaki demir bileşikleri yeşilimsi tona neden olur; özellikle camın kenarına bakılınca renk daha belirgin görülür.'),
  ('Vitray ile cam mozaik arasındaki temel fark hangisidir?', 'Vitray ışığı geçiren pencere, mozaik ise ışığı yansıtan duvar ya da zemin yüzeyidir', ['İkisi de aynı yöntemle yapılır; yalnızca boyutları farklıdır', 'Mozaik her zaman saydam cam kullanır ve pencereye uygulanır', 'Vitray yalnız taştan yapılır'], 'Vitray arkadan gelen ışıkla görünür; mozaik ise bir yüzeye harçla yerleştirilen tessera parçalarının yansıttığı ışıkla etkiler.'),
  ('Kristal kadeh bardakla vurunca uzun ve berrak bir çınlama veriyorsa bunun nedeni nedir?', 'Kurşun içeren camın yoğun ve elastik olması', ['Kadehin plastik olması ve içinin boş bırakılmış olması', 'Kadehin içindeki suyun hafifçe donmuş olması', 'Kadehin ahşap kaplı olması'], 'Kurşun oksitli cam titreşimi uzun süre sürdürür; bu nedenle kaliteli kristal kadeh çınlaması ayırt edici bir testtir.'),
  ('Bir koleksiyoncu, bir bardağın dibinde \'pontil izi\' ve içinde küçük kabarcıklar görüyor. Bu iki işaret birlikte neyi gösterir?', 'Elle üflenmiş ve pontile alınarak işlenmiş bir cam', ['Kalıba basılmış, fabrika üretimi ve elle işlenmemiş bir cam', 'Plastik enjeksiyonla üretilmiş, camsı görünümlü bir kap', 'Float cam kesimi'], 'Pontil izi el üflemesi ve çubukla işlemenin kanıtıdır; kabarcıklar da eski üretimde sık görülür. Birlikte el yapımına işaret eder.'),
  ('Bir cam sanatçısı, bir figürün kalıp içinde fırında eritilip dökülmesi (kiln casting) yöntemini hangi nedenle üflemeye tercih edebilir?', 'Daha kalın, hacimli ve heykelsi biçimler elde etmek için', ['Daha ince cidarlı ve hafif biçimler elde etmek için', 'Hiç fırın kullanmadan, soğuk işlemeyle şekil vermek için', 'Rengin kaybolması için'], 'Dökme camda kalın hacim ve ayrıntılı yüzey elde edilir; üfleme ise içi boş ve ince cidarlı biçimlere uygundur.'),
  ('Aalto\'nun 1933\'te tasarladığı ve yıllarca milyonlarca satan \'Stool 60\' tabureinin ayırt edici yapı özelliği nedir?', 'Bacakların tek parça bükülmüş kayın ağacından L biçiminde yapılıp oturağa bağlanması', ['Bacakların çelik borudan bükülüp oturağa kaynakla bağlanması', 'Oturağın tek parça kalıplanmış plastikten üretilip bacakla birleştirilmesi', 'Bacakların oyma ve geçmeli yapılması'], 'Aalto, ağacın ucunu bükerek \'L\' biçimli bacak elde etti; bu çözüm hem ucuz hem sağlam olup mobilya üretimini basitleştirdi.'),
  ('IKEA\'nın \'yassı paket\' (flat-pack) mobilya anlayışı, 1956\'da hangi pratik gözlemden doğmuştur?', 'Bir çalışanın masa bacaklarını söküp paketleyerek nakliye hasarını ve hacmini azaltması', ['Müşterilerin hazır masa istememesi ve montajı kendi yapmak istemesi', 'Ahşabın bulunamaması nedeniyle masaların parçalara ayrılması', 'Fabrikaların kapanması'], 'Mobilya parçalarını sökmek taşıma hacmini azaltıp fiyatı düşürdü; müşteri montajı üstlendi ve bu model dünya çapında yayıldı.'),
  ('Mobilya cilasında kullanılan gomalak (shellac) hangi kaynaktan elde edilir?', 'Güney Asya\'da yaşayan bir böceğin salgısından', ['Bir deniz salyangozunun salgı bezlerinden damıtılan boyar maddeden', 'Bir ağaç kabuğunun kaynatılıp yoğunlaştırılmasıyla elde edilen reçineden', 'Ham petrolün damıtılmasından elde edilen sentetik bir bağlayıcıdan'], 'Gomalak, lak böceğinin salgıladığı reçineden elde edilir; alkolde çözülüp mobilya yüzeyine tampon ile sürülür (Fransız cilası).'),
  ('A. W. N. Pugin\'in Victoria dönemi mobilya ve iç mekânda savunduğu üslup nedir?', 'Gotik Canlanma (Gothic Revival)', ['Rokoko (XV. Louis dönemi asimetrik, kıvrımlı saray üslubu)', 'Art Deco (1920\'ler platin, geometri ve lüks üslubu)', 'Bauhaus (1920\'ler Alman işlevselci tasarım okulu)'], 'Pugin, Orta Çağ Gotik biçimlerini dinî ve ahlaki gerekçeyle savundu; Parlamento Binası iç mekânı ve mobilyalar bu anlayışın örnekleridir.'),
  ('Bir marangoz, ahşap tahtayı keserken ve planyalarken yırtılmayı ve çatlamayı önlemek için ne yapar?', 'Tahtanın damarını kesilen yöne göre planlayıp yırtılmayı önleyecek biçimde keser', ['Damar yönüne bakmadan ve rastgele keser, çatlakları sonradan doldurur', 'Ahşabı önce suya batırıp yumuşatır, sonra damara karşı keser', 'Ahşabı camla kaplar'], 'Damara karşı kesim yırtık ve çatlak oluşturur; bu yüzden usta, planya ve testereyi damar yönüne uygun kullanır.'),
  ('Bir mobilya, nemli bir odada tahta yüzeyinde çatlak ve kıvrılma gösteriyor. Bu sorunun ana nedeni nedir?', 'Ahşabın nemi emip verirken genleşip büzülmesi', ['Tahtanın aşırı sert olması ve bu yüzden kendi ağırlığıyla kırılması', 'Tahtanın üzerine kurşun boya sürülmüş olması', 'Tahtanın taşlaşması'], 'Ahşap higroskopiktir; nem değişince boyutu değişir. Bu nedenle antik mobilyalarda zıvana ve kaplama dikkatle yapılırdı.'),
  ('Bir tasarımcı insan ölçülerine dayalı sandalye yapmak istiyor. Hangi veriye öncelik vermelidir?', 'Kullanıcıların oturma yüksekliği, bel desteği ve bacak uzunluğu ölçülerine', ['Sandalyenin rengine, kumaşın desenine ve parçanın etiketindeki yazıya', 'Sandalyenin fiyat politikasına ve mağaza düzenine', 'Sandalyenin ambalaj tasarımına ve kargo koşullarına'], 'Ergonomik tasarım, kullanıcı bedeninin ölçülerini temel alır; bu fikir Klint\'ten beri Danimarka modernizminin parçasıdır.'),
  ('Antik Mısır\'da kuvars kumu, alkali ve bakır katkılı hamurun şekillendirilip parlak turkuaz sırla kaplanmasıyla yapılan eşya türüne ne ad verilir?', 'Mısır fayansı', ['Terra sigillata', 'Sancai', 'Raku'], 'Mısır fayansı, kuvars esaslı hamurun sırlanmasıyla elde edilir; amuletler, boncuklar, kaplar ve karolar yapılmıştır.'),
  ('Antik Mısır mezarlarında ölünün öteki dünyada iş görmesi için konulan küçük mumya biçimli figürlere ne ad verilir?', 'Şabti (ushabti)', ['Skarabe (güneş tanrısı Khepri\'yi simgeleyen böcek biçimli amulet)', 'Kanopik kavanoz', 'Ankh'], 'Şabti figürleri fayans, ahşap ya da taştan yapılır; ölü için çalışacağına inanılırdı. Bazı mezarlarda yüzlerce şabti bulunur.'),
  ('Almanya\'daki Hildesheim\'de bulunan ve Roma gümüş sofra takımlarını içeren buluntuya genelde ne ad verilir?', 'Hildesheim Hazinesi', ['Troya Hazinesi', 'Karun Hazinesi', 'Sutton Hoo Hazinesi'], 'Hildesheim Hazinesi, 1868\'de bulunan 60 kadar Roma gümüş kap ve kadehten oluşur; kabartmalı süslemeleriyle Roma gümüşçülüğünün örneğidir.'),
  ('Pompeii ve Herculaneum\'daki evlerde bulunan masa, sedye ve lamba gibi mobilya ve eşya, bu kentlerin hangi bilgiyi korumuştur?', 'Roma ev yaşamı ve mobilya biçimleri hakkında doğrudan bilgi', ['Gotik mimarinin kökenini ve vitray yapımının ilk örneklerini', 'Çin İpek Yolu\'nun Roma\'ya uzanan güzergâhını ve ticaret ağını', 'Çin ipek yolunu'], 'Vezüv\'ün külleri organik malzemeyi kömürleştirerek korudu; böylece Roma ev eşyası ve süsleme biçimleri günümüze ulaştı.'),
  ('Antik Roma\'da aydınlatma için kullanılan pişmiş toprak yağ lambalarının çok yaygın olmasının nedeni nedir?', 'Ucuz, kalıpla seri üretilebilir ve zeytinyağıyla yanabilir olduğu için', ['Çok değerli ve sınırlı sayıda üretilen, yalnız saraylara özgü olması', 'Tamamen camdan yapılmış ve elle üflenmiş, her biri benzersiz olması', 'Elektrikle çalıştığı için'], 'Pişmiş toprak lambalar kalıpla basılıp binlerce adet yapılabiliyordu; üzerine kabartma sahneler de işlenirdi.'),
  ('Bir müzede bir kil kabın üzerinde silindirik küçük mühür basılarak oluşturulmuş sürekli bir şerit desen görülüyor. Bu desen en olası hangi kültürle bağlantılıdır?', 'Mezopotamya', ['Çin Han dönemi', 'Endülüs', 'Edo Japonya\'sı'], 'Silindir mühür, Mezopotamya\'da MÖ 4. binyılda ortaya çıkıp kil kaplar ve belgelerde sürekli frizler bırakmıştır.'),
  ('Mısır sanatında \'skarabe\' (hamamböceği) biçimli amuletlerin yaygın kullanılma nedeni nedir?', 'Yeniden doğuşu ve güneşin dolaşımını simgeleyen kutsal sayılması', ['Para yerine kullanılan, sınırlı ticaret değeri taşıyan bir ödeme aracı olması', 'Savaşlarda koruma sağlayan zırh parçası olarak taşınması', 'Mimaride taşıyıcı olarak kullanılması'], 'Skarabe, Khepri adlı güneş tanrısıyla ilişkilendirilmiş, yeniden doğuşun simgesidir; taş, fayans ve değerli taştan yapılmıştır.'),
  ('Arkeolog bir kazıda Fenike camının hangi biçimini bulduğunda bunun antik cam ticaretini gösterdiğini düşünür?', 'Renkli boncuk ve çekirdek tekniğiyle yapılmış küçük kaplar', ['Renksiz, temiz ve düzgün üflenmiş mutfak kapları', 'Roma çağından sonra yapılmış ince cidarlı kristal kadehler', 'Float cam levha'], 'Fenikeliler renkli cam boncukları ve çekirdek tekniğiyle yapılan küçük yağ şişelerini Akdeniz boyunca ticaret malı olarak taşıdılar; bu ürünler kazılarda geniş alanda bulunur.'),
  ('Bir kazıda aynı biçimli yüzlerce kırmızı parlak tabak bulunması, atölye üretimi hakkında neyi düşündürür?', 'Kalıp ve seri üretim kullanıldığını', ['Her kabın tek tek elle çarkta yapıldığını ve birbirine benzemediğini', 'Kapların başka bölgelerden ithal edildiğini ve yerel üretimin olmadığını', 'Kabın ithal olduğunu mutlaka'], 'Aynı biçim ve kabartma, çok sayıda aynı kalıbın kullanıldığını ve geniş bir üretim ağının varlığını gösterir.'),
  ('Sert hamurlu porselen ile yumuşak hamurlu porselen arasındaki temel fark nedir?', 'Sert hamur kaolinli ve yüksek ısıda, yumuşak hamur ise camlı frit karışımı ve daha düşük ısıda pişer', ['İkisinin hamuru tamamen aynıdır; fark yalnızca sırın rengindedir', 'Sert hamur yalnızca ahşap külü ve alçıdan yapılır', 'Yumuşak hamur daha yüksek ısıda pişer ve daha sert olur'], 'Yumuşak hamurlu porselen (pâte tendre) kil yerine cam fritiyle yapıldığından düşük ısıda pişer ama daha kırılgan olup sıcak renkler verir; Sèvres\'in ilk dönemi buna dayanır.'),
  ('Seramik yüzeyine bakır plaka gravürü ile hazırlanan desenin kâğıt aracılığıyla aktarılmasıyla yapılan süslemeye ne ad verilir?', 'Transfer baskı', ['Sgraffito', 'Barbotin', 'Lüster'], 'Gravürlü bakır levhaya mürekkep sürülür, ince kâğıda basılır, kâğıt seramik yüzeye yapıştırılıp çıkarılır; böylece desen çok sayıda parçaya hızla aktarılır.'),
  ('Mason\'s Ironstone gibi 19. yüzyıl İngiliz seramiklerinin amacı neydi?', 'Porselene benzeyen ama daha dayanıklı ve ucuz sofra takımı üretmek', ['Cam yerine kullanılabilecek, ışığı geçiren ince bir malzeme sağlamak', 'Gobelen ipliği yerine kullanılacak sağlam bir seramik lif üretmek', 'Metal döküm kalıbı olarak kullanılabilecek bir malzeme geliştirmek'], 'Taş hamurunun sert ve ağır olması dayanıklılık sağladı; Çin porselenini taklit eden desenlerle orta sınıf sofralarında yaygınlaştı.'),
  ('Stoke-on-Trent bölgesinin \'The Potteries\' adıyla anılmasının nedeni nedir?', 'Bölgede yüzlerce seramik atölyesi ve fabrikasının toplanması', ['Bölgede çok sayıda cam fabrikasının bulunup camın ihraç edilmesi', 'Bölgenin pamuklu kumaş dokumacılığıyla ünlenmesi', 'Bölgede kuyumculuğun ve mine işçiliğinin yaygın olması'], 'Staffordshire\'ın kil ve kömür yatakları, 18. yüzyıl boyunca Wedgwood, Spode ve Minton gibi fabrikaların yoğunlaşmasını sağladı.'),
  ('Seramik fabrikalarının 18. yüzyılda saraylar ya da asillerce desteklenmesinin sonucu nedir?', 'Porselen, saray prestiji ve diplomatik hediye olarak lüks sanat dalı haline gelmiştir', ['Seramik üretiminin tamamen yasaklanıp saray atölyelerinin kapatılması', 'Porselenin yalnızca sofra eşyası olarak sıradanlaşması', 'Camın porselenin yerini alması ve lüks seramik üretiminin bitmesi'], 'Meissen, Sèvres, Nymphenburg gibi kraliyet manufakturaları, hükümdarların itibar ve diplomasi araçları olarak büyük servisleri hediye etmesini sağladı.'),
  ('Bir porselen fincan kenarından kırık olduğunda iç yüzeyin camsı, çok ince ve parlak olduğu görülüyor. Bu özellik hangi hamurun işaretidir?', 'Sert hamurlu porselenin camsı ve sıkı yapısı', ['Çanak çömleğin gözenekli ve toprak gibi mat yapısı', 'Taş hamurun kaba, ağır ve sırsız yapısı', 'Terakotanın yumuşak, kırmızı ve gözenekli yapısı'], 'Yüksek ısıda pişen sert porselen camsı kırık yüzey verir; çanak çömlek ise toprak gibi mat ve gözenekli görünür.'),
  ('Müzede tarihsiz bir seramik kabın yaşının termolüminesans yöntemiyle belirlenmesi neye dayanır?', 'Pişirmeden beri kilde birikmiş radyasyon enerjisinin ısıtılınca ışık olarak salınmasına', ['Kilin rengi ve pişirme sırasında kazandığı yüzey parlaklığına', 'Kabın ağırlığı ve yüzeydeki sır tabakasının kalınlığına', 'Kabın vurulduğunda çıkardığı ses ve çınlama süresine'], 'Kil içindeki kristaller son pişirmeden itibaren doğal radyasyonu depolar; ısıtılınca salınan ışık miktarı geçen süreyi gösterir. Sahte tespitinde de kullanılır.'),
  ('Bir atölyede kil vazo kuruma sırasında kenarlarından çatlıyor. En olası neden hangisidir?', 'Duvarların eşit olmayan hızda kuruyup farklı büzülmesi', ['Kilin çok beyaz olması ve hamura fazla su katılması', 'Fırının fazla soğuk olması ve ısınmanın yavaş gerçekleşmesi', 'Fırçanın fazla yumuşak olması ve sırın çok kalın sürülmesi'], 'Hızlı ya da eşit olmayan kuruma, nem kaybını farklılaştırıp gerilim yaratır; bu da çatlak oluşturur. Kil önce yavaşça ve eşit kurutulmalıdır.'),
  ('Rönesans döneminde Gubbio\'daki Montefeltro Dükü\'nün çalışma odası (studiolo) duvarlarını kaplayan perspektifli ahşap mozaik tekniğine ne ad verilir?', 'Intarsia', ['Boiserie', 'Gesso', 'Grisaille'], 'Intarsia, farklı renkteki ahşap parçalarının kesilip birleştirilmesiyle perspektifli raflar, aletler ve manzaralar gibi resimli yüzeyler yaratır; Rönesans\'ın matematik ve görsel hünerini yansıtır.'),
  ('Rönesans\'ta prenslerin ve zenginlerin \'merak odası\' (Wunderkammer, Kunstkammer) adı verilen koleksiyonlarında neler bir arada sergilenirdi?', 'Doğal nesneler, egzotik eşyalar, sanat yapıtları ve bilimsel aletler', ['Yalnızca yağlıboya tablolar ve gravürler ile tarihî belgeler', 'Yalnızca silah ve zırh koleksiyonları ile av ganimetleri', 'Yalnızca değerli taşlar ve altın işlemeli mücevherler'], 'Merak odaları, mercandan hindistan cevizi kadehlere, deniz kabuklarından saatlere uzanan dünyanın küçük bir modelini kurmayı amaçlardı; müzelerin öncülüdür.'),
  ('Almanya\'da Augsburg ve Nürnberg atölyelerinin 16. yüzyılda ürettiği ve gemi biçimli masa süsü olarak kullanılan gümüş eşyaya ne ad verilir?', 'Nef', ['Rhyton', 'Ewer', 'Reliquary'], 'Nef, genellikle gümüş ve yaldızla yapılan gemi biçimli bir sofra süsüdür; tuz, baharat ya da peçeteyi barındırır, ev sahibinin zenginliğini gösterir.'),
  ('Venedik\'te 16. yüzyıldan itibaren pahalı ve prestijli sayılan, el ile üflenmiş ve kalay-cıva amalgamla kaplanmış ayna, sarayların hangi özelliğini gösterirdi?', 'Zenginlik ve teknik üstünlüğü', ['Hanedanın yoksulluğunu ve mali sıkıntısını', 'Savaş hazırlığını ve ordunun donanımını', 'Tarımsal üretimin bolluğunu ve arazi büyüklüğünü'], 'Büyük aynalar çok pahalıydı; Venedik\'in ayna tekeli yüzünden saraylar ve zenginler onları statü sembolü olarak sergilerdi.'),
  ('Barok saray yaşamında hükümdarın iktidarını gösteren dekoratif sanatlar hangi niteliklerle öne çıkar?', 'Gösterişli malzeme, bol yaldız ve büyük ölçekli simetrik düzen', ['Süssüz yalın ahşap, sade çizgiler ve mat yüzeyler', 'Soluk renkli, ölçülü seramik ve düz duvarlar', 'Çıplak beton'], 'Barok saraylarda yaldızlı mobilya, gobelen ve dev aynalar, hükümdarın gücünü sahnelenmiş bir görsel dünyayla gösterirdi.'),
  ('Bir tarihçi, 17. yüzyıl Hollanda natürmortlarında Çin porseleninin sık görülmesini nasıl yorumlar?', 'Çin porselenlerinin ticaretle zenginleşen burjuvanın prestij nesnesi olması', ['Hollanda\'da porselen üretiminin hiç olmaması ve ithalatın zorunlu olması', 'Porselenin yalnız saraylarda yasaklı olması ve burjuvaya satılamaması', 'Resim tekniğinin yasaklanıp yalnız natürmort yapılmasına izin verilmesi'], 'Hollanda Doğu Hindistan Şirketi\'nin ithal ettiği Çin porselenleri varlık ve çağdaş dünya ticaretinin simgesi hâline gelerek natürmortlarda yer aldı.'),
  ('Bir müşteri, birkaç yıl önce aldığı beyaz altın yüzüğün zamanla sarımsı bir ton kazandığını fark ediyor. En olası açıklama hangisidir?', 'Üzerindeki rodyum kaplamanın aşınıp alttaki hafif sarımsı alaşımın görünmesi', ['Altının oksitlenip kararması', 'Taşların renk değiştirmesi', 'Yüzüğün gümüşten yapılmış olması'], 'Beyaz altının parlak beyazlığı çoğu zaman ince rodyum kaplamadan gelir; kaplama aşınınca altın alaşımının doğal soluk sarı rengi ortaya çıkar.'),
  ('Kararmış bir gümüş çatalın alüminyum folyo, sıcak su ve kabartma tozu ile temizlenmesi neye dayanır?', 'Gümüş sülfürün kimyasal tepkimeyle gümüşe geri dönmesine', ['Gümüşün erimesine', 'Gümüşün boyanmasına', 'Gümüşün cilalanarak aşınmasına'], 'Alüminyum, gümüşten daha etkin bir metaldir; sodalı sıcak suda gümüş sülfürdeki kükürtü alır ve gümüş yeniden metalik hâle gelir. Cilaya göre aşındırma olmaz.'),
  ('Nikel içeren beyaz altın bir yüzük takınca bazı insanlarda cilt reaksiyonu görülür. Kuyumcu hangi alternatifi önerebilir?', 'Paladyumla alaşımlanmış beyaz altın ya da platin', ['Daha çok nikel içeren alaşım', 'Bakır kaplamalı gümüş', 'Kalay kaplama'], 'Nikel yaygın bir alerjendir; paladyumlu beyaz altın ve platin hipoalerjenik sayılır ve alerjisi olan müşteriler için uygundur.'),
  ('Bir yün kazağın sıcak suda ve sürtünmeyle çamaşır makinesinde çekip sertleşmesi, hangi olayın sonucudur?', 'Yün lifi pullarının birbirine kilitlenerek keçeleşmesi', ['Yünün erimesi', 'Yünün boyanması', 'Yünün selülozlaşması'], 'Sıcak su ve mekanik hareket, yün liflerinin pullarını birbirine geçirir; böylece kazak keçeleşip küçülür. Bu keçe yapımının da temelidir.'),
  ('Bir ürünün jakar mı yoksa baskı mı olduğunu anlamak için kumaşın ters yüzüne bakan kişi neyi inceler?', 'Dokuma desenlerde ters yüzde iplik atlamalarının görülmesini, baskıda ise desenin soluk görünmesini', ['Kumaşın kokusunu', 'Kumaşın ağırlığını', 'Kumaşın etiketini'], 'Jakar desen dokunarak oluştuğundan ters yüzde uzun atkı atlamaları görülür; baskılı kumaşta desen yüzeye bastırıldığı için ters yüz genellikle soluktur.'),
  ('Bir müze, tarihî bir ipek kaftanı sergilerken düşük ışık, morötesi filtre ve yatay düzlem kullanıyor. Bu önlemlerin başlıca amacı nedir?', 'Işık ve ağırlığın liflerde yol açacağı zayıflama ve yırtılmayı önlemek', ['Kumaşın renginin değişmesini sağlamak', 'Kumaşın kokusunu artırmak', 'Kumaşın ağırlığını artırmak'], 'İpek ışıkla zayıflar; dikey asıldığında kumaşın kendi ağırlığı lifleri gerer. Bu yüzden loş ışık ve yatay yatırma korunmayı sağlar.'),
  ('Dokumada çözgü sıklığı yüksek bir tezgâhın, düşük sıklıklı olana göre sağladığı olanak nedir?', 'Daha ince ayrıntılı desenlerin dokunabilmesi', ['Daha kaba bir yüzey', 'Daha az iplik kullanımı', 'Daha kısa üretim süresi'], 'Birim alana düşen çözgü ve atkı sayısı arttıkça çizgiler ve kıvrımlar daha ince verilebilir; bu yüzden ince portre dokumaları çok sık çözgü ister.'),
  ('Bir cam levhayı kesmek için cam kesici ile ince bir çizik atılıp ardından hafifçe bastırmak neden camı çizgi boyunca kırar?', 'Çizgi, gerilimi o hatta toplayıp çatlağı oradan başlatır', ['Cam çizgide eriyip ayrılır', 'Cam bıçakla kesilir', 'Cam manyetik olarak yarılır'], 'Çizik cam yüzeyinde bir zayıf hat oluşturur; bükme gerilimi bu hatta yoğunlaşır ve çatlak çizgi boyunca ilerler.'),
  ('Bir ahşap masada sıcak bardağın bıraktığı beyaz halka leke, hangi nedenden doğar?', 'Cila tabakasında hapsolmuş nemin ışığı dağıtması', ['Ağacın erimesi', 'Cilanın yanması', 'Boyanın rengi'], 'Sıcak bardak, cila içine girmiş nemi hapseder; nem ışığı dağıtınca beyaz bir leke görünür. Gomalak gibi alkolde çözünür cilalar bu lekeyi alabilir.'),
  ('Bir sandalye bacağının zıvana eklemlerinin zamanla gevşemesinin başlıca nedeni nedir?', 'Ahşabın nem değişimleriyle büzülmesi ve tutkalın zayıflaması', ['Ahşabın kendiliğinden erimesi', 'Zıvananın cama dönüşmesi', 'Çivinin altına dönüşmesi'], 'Ahşap, mevsimsel nem değişikliğiyle genleşip büzülür; bu hareket tutkal bağlantısını yorarak zıvanayı gevşetir.'),
  ('Dekoratif sanat ile güzel sanat arasındaki ayrım hakkında hangi ifade eleştirel biçimde doğrudur?', 'Ayrım tarihsel ve toplumsal bir yargıdır; birçok dekoratif sanat eseri estetik değer taşır', ['Dekoratif sanat hiç güzel olamaz', 'Güzel sanat hiç işlev taşımaz', 'İki alan tamamen aynıdır'], 'Bu ayrım Rönesans\'tan sonra sanat akademileri ve piyasa tarafından yerleştirilmiştir; Bauhaus ve Arts and Crafts gibi hareketler bunu aşmaya çalışmıştır.'),
  ('Hand-made (el yapımı) ve seri üretimli iki aynı biçimli vazo aynı müzede sergileniyor. Sergi etiketinde hangi bilginin bulunması izleyiciye daha çok öğretici olur?', 'Üretim yöntemi, malzeme ve atölye bilgisi', ['Yalnız fiyatı', 'Yalnız bağışçının adı', 'Yalnız rengi'], 'Teknik ve üretim bilgisi, nesnenin tasarım ve emek bağlamını anlatır; aynı biçimin farklı üretim koşullarını karşılaştırmak mümkün olur.'),
  ('Bir tasarımcı, doğal kök boya ile sentetik boyanın karşılaştırmasını yaparken sentetik boyanın hangi üstünlüğünü belirtebilir?', 'Daha geniş renk yelpazesi, tekrarlanabilirlik ve düşük maliyet', ['Hiç çevresel etkisi olmaması', 'Daha az ışık haslığı', 'Daha uzun üretim süresi'], 'Sentetik boyalar sabit tonlarda çok sayıda renk üretir ve ucuzdur; ancak su kirliliği gibi çevresel sonuçları olabilir. Doğal boyalar ise daha sınırlı ama kendine özgü tonlar verir.'),
  ('Bir koleksiyoncu aynı model bir bardağın el üflemesi mi kalıp ürünü mü olduğunu anlamak için neye bakar?', 'Kalıp dikiş izine ve çeperdeki kalınlık farklarına', ['Bardağın etiketine', 'Bardağın kokusuna', 'Bardağın ağırlığına yalnızca'], 'Kalıp ürünü camda çoğu zaman dikey bir kalıp çizgisi ve düzenli çeper bulunur; el üflemesi eşyada kalınlık ve biçim hafifçe değişir.'),
  ('Bir sanat tarihçisi Tiffany ve Gallé camlarını karşılaştırıyor. İkisinin ortak özelliği nedir?', 'Art Nouveau\'nun doğadan esinli cam ve renk anlayışını yansıtmaları', ['Tamamen şeffaf cam üretmeleri', 'Yalnız endüstriyel üretim yapmaları', 'Sadece Çin\'den etkilenmeleri'], 'İki sanatçı da bitkisel ve doğal motifli, renkli ve yenilikçi cam teknikleriyle Art Nouveau\'nun cam sanatındaki temsilcileridir; biri New York\'ta biri Nancy\'de çalıştı.'),
  ('1955\'te General Electric\'in başardığı ve elmasın yapay üretiminde dönüm noktası sayılan işlem hangisidir?', 'Grafitin yüksek basınç ve yüksek ısıda elmasa dönüştürülmesi', ['Elmasın kömürden kesilmesi', 'Cam parçalarının sırlanması', 'Altının eritilmesi'], 'Yüksek basınç-yüksek sıcaklık (HPHT) yöntemi, karbonu elmasın oluştuğu koşullara benzer ortama sokar; bu yöntem sanayi elmasının temelini oluşturdu.'),
  ('Kübik zirkonya, elmas taklidi olarak neden çok yaygınlaşmıştır?', 'Laboratuvarda ucuza üretilebilir ve renksiz, parlak olabilir', ['Doğada çok bol bulunur', 'Elmastan daha sert olması nedeniyle', 'Elmastan daha ağır olması nedeniyle'], '1970\'lerde Sovyet laboratuvarlarında üretimi ticarileşen kübik zirkonya, ucuz ve berrak olduğundan elmas taklidi olarak kullanılır; sertliği elmastan düşüktür.'),
  ('Türkiye\'de düğünlerde yaygın hediye edilen 22 ayar bilezik, binde kaç saf altın içerir?', 'Yaklaşık 916', ['Yaklaşık 750', 'Yaklaşık 585', 'Yaklaşık 999'], '22/24 oranı yaklaşık 0,9167\'dir; 22 ayar altın binde 916 saf altın içerir. Bu oran 18 ayar için 750, 14 ayar için 585\'tir.'),
  ('Opak yıldızlı safirlerde ışık yansıması sonucu görülen yıldız biçimli parlak çizgilere ne ad verilir?', 'Asterizm', ['Dispersiyon', 'Pleokroizm', 'Fosforesans'], 'Yıldızlı safirde mikroskobik rutil iğneleri ışığı yansıtır ve kabaşon kesimde altı kollu yıldız oluşur; bu etkiye asterizm denir.'),
  ('Londra Kulesi\'ndeki Jewel House\'ta sergilenen İngiliz Kraliyet Mücevherleri hangi amaçla kullanılır?', 'Taç giyme törenleri ve devlet törenlerinde hükümdarın otoritesini simgelemek için', ['Müzik aleti olarak', 'Seramik fırını yapmak için', 'Cam mozaik yapmak için'], 'Taçlar, asalar ve küreler, hükümdarın otoritesini simgeleyen törensel nesnelerdir; bunların bir bölümü 1661\'de yenilenen taç takımına dayanır.'),
  ('Kehribar ve inci gibi mücevherlerin diğer taşlara göre çok daha yumuşak olması neye yol açar?', 'Çabuk çizilmeleri ve özel bakım gerektirmeleri', ['Daha uzun ömürlü olmaları', 'Daha parlak olmaları', 'Hiç kırılmamaları'], 'Mohs ölçeğinde düşük sertlikteki taşlar günlük kullanımda çizilir; bu yüzden yüzük yerine küpe ya da kolye gibi daha az aşınan takılarda tercih edilir.'),
  ('Bir müşteri, 5 gramlık bir 14 ayar yüzükte (binde 585) kaç gram saf altın olduğunu soruyor.', '2,925 gram', ['3,5 gram', '2,5 gram', '4,2 gram'], '5 × 0,585 = 2,925 gram saf altın vardır; kalan ağırlık gümüş, bakır gibi alaşım metallerinden oluşur.'),
  ('Her biri 0,25 karat olan 12 küçük elmasla bezeli bir kolyedeki toplam elmas ağırlığı kaç gramdır? (1 karat = 0,2 g)', '0,6 gram', ['3 gram', '0,3 gram', '1,2 gram'], '12 × 0,25 = 3 karat; 3 × 0,2 = 0,6 gramdır.'),
  ('Kızılırmak\'ın kızıl kilinin kullanıldığı ve Hititler\'den beri sürdüğü söylenen Nevşehir\'deki çömlekçilik geleneği hangi ilçede yaşatılır?', 'Avanos', ['Ürgüp', 'Göreme', 'Nevşehir merkez'], 'Avanos\'ta çömlekçiler Kızılırmak\'ın kırmızı çamurunu tekme çarkında işleyerek testi, çanak ve süs eşyası yapar; kırmızı ve sırlı yüzeylerle ünlüdür.'),
  ('Bursa\'da 1491\'de II. Bayezid zamanında yapılan ve ipek böceği kozalarının ticaretinin merkezi olan han hangisidir?', 'Koza Han', ['Emir Han', 'Fidan Han', 'Geyve Han'], 'Koza Han, ipekçiliğin merkezi Bursa\'da ipek kozası alım satımının yapıldığı büyük bir hândır; Ulu Cami\'nin yakınındadır.'),
  ('Doğal boyalı yün ipliklerin güneşte rengin yavaş yavaş açılmasının sebebi nedir?', 'Boya moleküllerinin morötesi ışınlarla parçalanması', ['Yünün erimesi', 'Yünün çürümesi', 'Yünün parlaması'], 'Işık haslığı düşük doğal boyalar morötesi ışınlarda kimyasal bozunur; iyi mordanlama ve uygun boya kullanımı bu etkiyi azaltır.'),
  ('Bir müşteri, iki ipek eşarptan biri kemha, diğeri düz saten dokuma. Kemha eşarbın ayırt edici özelliği hangisidir?', 'Altın ya da gümüş iplikle yapılan ek atkıyla kabarık desenler', ['Düz parlak yüzey', 'Havlı yüzey', 'Tamamen baskılı desen'], 'Kemha, çözgü ve atkı sistemine metal iplikli ek atkı eklenerek desenin kumaş üzerinde kabarık ve parlak biçimde oluşmasıdır.'),
  ('Bir ev sahibi, balkondaki ahşap sandalyenin yağmur ve güneşe dayanması için hangi yüzey işlemini seçmelidir?', 'Dış mekâna uygun verniği ya da yağı', ['Çok ince ipek kaplama', 'Yalnız mum cila', 'Boyasız bırakma'], 'Dış mekân verniği ya da tik yağı, ahşabın nemden ve morötesi ışınlardan korunmasını sağlar; iç mekân cilaları dış etkiye dayanıklı değildir.'),
  ('Japonya\'da Jōmon kültürüne ait, yüzeyi ip izleriyle süslenmiş kaplar hangi nedenle önemlidir?', 'Dünyanın bilinen en eski seramik geleneklerinden birine ait olmaları', ['Roma çağına tarihlenmeleri', 'Porselenin ilk örnekleri olmaları', 'Avrupa\'dan ithal edilmiş olmaları'], 'Jōmon, \'ip izi\' anlamına gelir; Japonya\'daki bu seramikler yaklaşık 16.000 yıl öncesine kadar gider ve avcı-toplayıcılar tarafından yapılmıştır.'),
  ('Bir arkeolog, bir yerleşimde taştan yapılmış dolap ve yatak buluyor. Bu buluntu en olası hangi çevre koşulunu düşündürür?', 'Ağacın az, taşın bol olduğu bir bölge', ['Bolca tropikal orman bulunan bir bölge', 'Denizin dibinde bir yerleşim', 'Cam üretimi yapılan bir şehir'], 'Skara Brae gibi ağaçsız adalarda insanlar mobilyayı taştan yapmıştır; malzeme seçimi çevre koşullarına göre şekillenir.'),
];
